export const COLLECTOR_FILES: Record<string, string> = {
  "config.example.json": "{\n  \"site_url\": \"https://your-site.vercel.app\",\n  \"ingest_key\": \"paste-the-INGEST_KEY-here\",\n  \"league_path\": \"\",\n  \"min_players\": 2\n}\n",
  "custy_collector.py": "#!/usr/bin/env python3\n\"\"\"\ncusty.gg collector\n\nWatches the League of Legends client on this computer and uploads every\ncustom game you play to your custy.gg site. Uses only the Python standard\nlibrary, so there is nothing to pip install.\n\nUsage:\n    python custy_collector.py            run forever (checks every minute)\n    python custy_collector.py --once     upload any new custom games, then exit\n    python custy_collector.py --test     check config, League client and site\n    python custy_collector.py --all      re-send every custom game in history\n    python custy_collector.py --review   open the game review page (test)\n\nSettings live in config.json next to this file.\n\nPackaged as custy-collector.exe (see collector/windows_app.py), the same code\nruns as a one-click Windows app: the site's address and upload key are\nattached to the end of the .exe when it is downloaded, double-clicking it\ninstalls it to %LOCALAPPDATA%/custy-collector and starts it with Windows.\n\"\"\"\n\nimport base64\nimport json\nimport logging\nimport os\nimport platform\nimport re\nimport ssl\nimport subprocess\nimport sys\nimport time\nimport urllib.error\nimport urllib.request\n\nVERSION = \"1.7.4\"\nFROZEN = bool(getattr(sys, \"frozen\", False))\nif FROZEN:\n    # Packaged app: keep config, state and log in the user's app-data folder.\n    HERE = os.path.join(os.environ.get(\"LOCALAPPDATA\") or os.path.expanduser(\"~\"), \"custy-collector\")\n    os.makedirs(HERE, exist_ok=True)\nelse:\n    HERE = os.path.dirname(os.path.abspath(__file__))\nCONFIG_PATH = os.path.join(HERE, \"config.json\")\nSTATE_PATH = os.path.join(HERE, \"uploaded.json\")\nLOG_PATH = os.path.join(HERE, \"collector.log\")\n\nPOLL_SECONDS = 60          # how often to look for new games while idle\nAFTER_GAME_DELAY = 20      # wait this long after a game ends before checking\nHISTORY_PAGE = 50          # how many recent games to look through each check\n\nDEFAULT_LEAGUE_DIRS = [\n    r\"C:\\Riot Games\\League of Legends\",\n    r\"D:\\Riot Games\\League of Legends\",\n    r\"C:\\Program Files\\Riot Games\\League of Legends\",\n    r\"C:\\Program Files (x86)\\Riot Games\\League of Legends\",\n    \"/Applications/League of Legends.app/Contents/LoL\",\n]\n\nlog = logging.getLogger(\"custy\")\n\n\n# --------------------------------------------------------------------------\n# Config and local state\n# --------------------------------------------------------------------------\n\nTRAILER_START = b\"\\n#CUSTY-CONFIG#\"\nTRAILER_END = b\"#END-CUSTY-CONFIG#\"\n\n\ndef embedded_config(path=None):\n    \"\"\"Settings the website attached to the end of this .exe, or None.\"\"\"\n    path = path or (sys.executable if FROZEN else None)\n    if not path:\n        return None\n    try:\n        with open(path, \"rb\") as f:\n            f.seek(0, os.SEEK_END)\n            size = f.tell()\n            f.seek(max(0, size - 8192))\n            tail = f.read()\n    except OSError:\n        return None\n    start = tail.rfind(TRAILER_START)\n    end = tail.rfind(TRAILER_END)\n    if start < 0 or end < start:\n        return None\n    try:\n        return json.loads(tail[start + len(TRAILER_START):end].decode(\"utf-8\"))\n    except ValueError:\n        return None\n\n\ndef load_config():\n    cfg = embedded_config()\n    if cfg is None:\n        if not os.path.exists(CONFIG_PATH):\n            raise SystemExit(\n                \"config.json is missing. Copy config.example.json to config.json \"\n                \"and fill in site_url and ingest_key.\"\n            )\n        with open(CONFIG_PATH, \"r\", encoding=\"utf-8\") as f:\n            cfg = json.load(f)\n    site = (cfg.get(\"site_url\") or \"\").strip().rstrip(\"/\")\n    key = (cfg.get(\"ingest_key\") or \"\").strip()\n    if not site or \"your-site\" in site:\n        raise SystemExit(\"Set site_url in config.json to your custy.gg site address.\")\n    if not key or key == \"paste-the-INGEST_KEY-here\":\n        raise SystemExit(\"Set ingest_key in config.json (same value as INGEST_KEY on the site).\")\n    cfg[\"site_url\"] = site\n    cfg[\"ingest_key\"] = key\n    cfg.setdefault(\"league_path\", \"\")\n    cfg.setdefault(\"min_players\", 2)\n    return cfg\n\n\ndef load_state():\n    try:\n        with open(STATE_PATH, \"r\", encoding=\"utf-8\") as f:\n            return set(json.load(f))\n    except (OSError, ValueError):\n        return set()\n\n\ndef save_state(seen):\n    tmp = STATE_PATH + \".tmp\"\n    with open(tmp, \"w\", encoding=\"utf-8\") as f:\n        json.dump(sorted(seen), f)\n    os.replace(tmp, STATE_PATH)\n\n\nTIMELINE_STATE = STATE_PATH.replace(\".json\", \"\") + \"-timelines.json\"\n\n\ndef load_timeline_state():\n    try:\n        with open(TIMELINE_STATE, \"r\", encoding=\"utf-8\") as f:\n            return set(json.load(f))\n    except (OSError, ValueError):\n        return set()\n\n\ndef save_timeline_state(done):\n    tmp = TIMELINE_STATE + \".tmp\"\n    with open(tmp, \"w\", encoding=\"utf-8\") as f:\n        json.dump(sorted(done), f)\n    os.replace(tmp, TIMELINE_STATE)\n\n\nTIMELINE_EVENTS = {\"CHAMPION_KILL\", \"ELITE_MONSTER_KILL\", \"BUILDING_KILL\", \"ITEM_PURCHASED\", \"ITEM_UNDO\",\n                   \"ITEM_SOLD\", \"SKILL_LEVEL_UP\", \"WARD_PLACED\", \"WARD_KILL\", \"CHAMPION_SPECIAL_KILL\"}\n\n\ndef slim_timeline(tl):\n    \"\"\"Drops event types the site doesn't use, to keep the upload small.\"\"\"\n    out = dict(tl)\n    out[\"frames\"] = [dict(f, events=[e for e in (f.get(\"events\") or []) if e.get(\"type\") in TIMELINE_EVENTS])\n                     for f in tl.get(\"frames\") or []]\n    return out\n\n\ndef send_timeline(cfg, lcu, key, game_id):\n    \"\"\"Uploads one game's timeline. Returns True when the site has it (or can't use it), so we stop trying.\"\"\"\n    try:\n        tl = lcu.get(\"/lol-match-history/v1/game-timelines/%s\" % game_id)\n    except (urllib.error.URLError, OSError, ValueError) as e:\n        log.info(\"No timeline for %s from the client: %s\", key, e)\n        return True\n    if not tl or not tl.get(\"frames\"):\n        log.info(\"No timeline for %s from the client\", key)\n        return True\n    tl = slim_timeline(tl)\n    status, body = post_json(cfg[\"site_url\"] + \"/api/timeline\", cfg[\"ingest_key\"], {\"id\": key, \"timeline\": tl})\n    if status in (200, 201):\n        log.info(\"Uploaded timeline for %s\", key)\n        return True\n    if status in (404, 413, 422):\n        log.warning(\"Site couldn't take the timeline for %s (HTTP %s): %s\", key, status, body.get(\"error\", \"\"))\n        return True\n    log.warning(\"Timeline upload for %s failed (HTTP %s), will retry\", key, status)\n    return False\n\n\n# --------------------------------------------------------------------------\n# Finding the League client\n# --------------------------------------------------------------------------\n\ndef _client_command_line():\n    \"\"\"Return the command line of the running LeagueClientUx process, or ''.\"\"\"\n    system = platform.system()\n    try:\n        if system == \"Windows\":\n            cmd = [\n                \"powershell\", \"-NoProfile\", \"-NonInteractive\", \"-Command\",\n                \"Get-CimInstance Win32_Process -Filter \\\"name='LeagueClientUx.exe'\\\" \"\n                \"| Select-Object -ExpandProperty CommandLine\",\n            ]\n            flags = 0x08000000  # CREATE_NO_WINDOW, so no console flashes when running hidden\n            out = subprocess.run(cmd, capture_output=True, text=True, timeout=15,\n                                 creationflags=flags)\n            return out.stdout or \"\"\n        out = subprocess.run([\"ps\", \"-A\", \"-o\", \"command\"], capture_output=True,\n                             text=True, timeout=10)\n        for line in out.stdout.splitlines():\n            if \"LeagueClientUx\" in line and \"--app-port\" in line:\n                return line\n    except (OSError, subprocess.SubprocessError):\n        pass\n    return \"\"\n\n\ndef _read_lockfile(folder):\n    try:\n        with open(os.path.join(folder, \"lockfile\"), \"r\", encoding=\"utf-8\") as f:\n            parts = f.read().strip().split(\":\")\n        if len(parts) >= 5:\n            return int(parts[2]), parts[3]\n    except (OSError, ValueError):\n        pass\n    return None\n\n\ndef find_client(cfg):\n    \"\"\"Return (port, password) for the running League client, or None.\"\"\"\n    # The client writes a lockfile while it's open and deletes it on exit.\n    # Checking the usual install folders first is cheap.\n    dirs = ([cfg[\"league_path\"]] if cfg.get(\"league_path\") else []) + DEFAULT_LEAGUE_DIRS\n    for d in dirs:\n        creds = _read_lockfile(d)\n        if creds:\n            return creds\n\n    # League installed somewhere else: ask the operating system.\n    cmdline = _client_command_line()\n    port = re.search(r\"--app-port=(\\d+)\", cmdline)\n    token = re.search(r\"--remoting-auth-token=([\\w-]+)\", cmdline)\n    if port and token:\n        return int(port.group(1)), token.group(1)\n    install = re.search(r'--install-directory=([^\"]+?)(?:\"|\\s--|$)', cmdline)\n    if install:\n        return _read_lockfile(install.group(1).strip())\n    return None\n\n\nclass LeagueClient:\n    \"\"\"Tiny wrapper around the client's local API on 127.0.0.1.\"\"\"\n\n    def __init__(self, port, password):\n        self.base = \"https://127.0.0.1:%d\" % port\n        auth = base64.b64encode((\"riot:%s\" % password).encode()).decode()\n        self.headers = {\"Authorization\": \"Basic \" + auth, \"Accept\": \"application/json\"}\n        # The client uses a self-signed certificate. This context is only ever\n        # used for requests to 127.0.0.1, never for the internet.\n        self.ctx = ssl.create_default_context()\n        self.ctx.check_hostname = False\n        self.ctx.verify_mode = ssl.CERT_NONE\n\n    def get(self, path):\n        req = urllib.request.Request(self.base + path, headers=self.headers)\n        with urllib.request.urlopen(req, context=self.ctx, timeout=20) as resp:\n            body = resp.read()\n        return json.loads(body) if body else None\n\n\n# --------------------------------------------------------------------------\n# Talking to the custy.gg site\n# --------------------------------------------------------------------------\n\ndef post_json(url, key, payload):\n    data = json.dumps(payload).encode(\"utf-8\")\n    req = urllib.request.Request(\n        url, data=data, method=\"POST\",\n        headers={\n            \"Content-Type\": \"application/json\",\n            \"Authorization\": \"Bearer \" + key,\n            \"User-Agent\": \"custy-collector/\" + VERSION,\n        },\n    )\n    try:\n        with urllib.request.urlopen(req, timeout=30) as resp:\n            return resp.status, json.loads(resp.read() or b\"{}\")\n    except urllib.error.HTTPError as e:\n        try:\n            body = json.loads(e.read() or b\"{}\")\n        except ValueError:\n            body = {}\n        return e.code, body\n\n\ndef check_site(cfg):\n    req = urllib.request.Request(\n        cfg[\"site_url\"] + \"/api/ingest\",\n        headers={\"Authorization\": \"Bearer \" + cfg[\"ingest_key\"],\n                 \"User-Agent\": \"custy-collector/\" + VERSION},\n    )\n    try:\n        with urllib.request.urlopen(req, timeout=20) as resp:\n            return resp.status, json.loads(resp.read() or b\"{}\")\n    except urllib.error.HTTPError as e:\n        return e.code, {}\n    except (urllib.error.URLError, OSError) as e:\n        return 0, {\"error\": str(e)}\n\n\n# --------------------------------------------------------------------------\n# Finding and uploading custom games\n# --------------------------------------------------------------------------\n\ndef game_key(game):\n    return \"%s-%s\" % (game.get(\"platformId\") or \"NA\", game.get(\"gameId\"))\n\n\ndef is_custom(game):\n    return game.get(\"gameType\") == \"CUSTOM_GAME\"\n\n\ndef human_count(game):\n    count = 0\n    for ident in game.get(\"participantIdentities\") or []:\n        player = ident.get(\"player\") or {}\n        puuid = player.get(\"puuid\") or \"\"\n        if puuid and set(puuid.replace(\"-\", \"\")) != {\"0\"}:\n            count += 1\n    return count\n\n\ndef recent_games(lcu):\n    data = lcu.get(\n        \"/lol-match-history/v1/products/lol/current-summoner/matches\"\n        \"?begIndex=0&endIndex=%d\" % HISTORY_PAGE\n    )\n    games = (data or {}).get(\"games\") or {}\n    if isinstance(games, dict):\n        games = games.get(\"games\") or []\n    return games\n\n\ndef sync(cfg, lcu, seen, me, force=False):\n    \"\"\"Upload any custom games not uploaded before. Returns how many were new to the site.\"\"\"\n    uploaded = 0\n    created = 0\n    new_players = set()\n    timelines = load_timeline_state()\n    timelines_before = len(timelines)\n    for summary in recent_games(lcu):\n        if not is_custom(summary):\n            continue\n        key = game_key(summary)\n        if key in seen and not force:\n            # Games uploaded before timelines existed: send their timeline once.\n            if key not in timelines and send_timeline(cfg, lcu, key, summary[\"gameId\"]):\n                timelines.add(key)\n            continue\n        try:\n            game = lcu.get(\"/lol-match-history/v1/games/%s\" % summary[\"gameId\"])\n        except (urllib.error.URLError, OSError, ValueError) as e:\n            log.warning(\"Could not read game %s from the client: %s\", key, e)\n            continue\n        if not game or not game.get(\"participants\"):\n            continue\n        if human_count(game) < int(cfg.get(\"min_players\", 2)):\n            log.info(\"Skipping %s: fewer than %s players\", key, cfg.get(\"min_players\", 2))\n            seen.add(key)\n            continue\n\n        status, body = post_json(\n            cfg[\"site_url\"] + \"/api/ingest\", cfg[\"ingest_key\"],\n            {\"game\": game, \"uploader\": me, \"collectorVersion\": VERSION},\n        )\n        if status in (200, 201):\n            seen.add(key)\n            uploaded += 1\n            if body.get(\"needTimeline\") and key not in timelines:\n                if send_timeline(cfg, lcu, key, summary[\"gameId\"]):\n                    timelines.add(key)\n            elif not body.get(\"needTimeline\"):\n                timelines.add(key)\n            if body.get(\"status\") == \"exists\":\n                log.info(\"Custom game %s is already on the site\", key)\n            else:\n                created += 1\n                log.info(\"Uploaded custom game %s\", key)\n                for ident in game.get(\"participantIdentities\") or []:\n                    puuid = (ident.get(\"player\") or {}).get(\"puuid\") or \"\"\n                    if puuid and set(puuid.replace(\"-\", \"\")) != {\"0\"}:\n                        new_players.add(puuid)\n        elif status == 401:\n            raise SystemExit(\"The site rejected the ingest_key in config.json. Check it matches INGEST_KEY.\")\n        else:\n            log.warning(\"Upload of %s failed (HTTP %s): %s\", key, status, body.get(\"error\", \"\"))\n    if uploaded:\n        save_state(seen)\n    if len(timelines) != timelines_before:\n        save_timeline_state(timelines)\n    if new_players:\n        try:\n            send_ranks(cfg, lcu, new_players)\n        except Exception as e:\n            log.warning(\"Couldn't send ranks: %s\", e)\n    return created\n\n\n# --------------------------------------------------------------------------\n# Who's in the custom lobby (for the Discord team maker)\n# --------------------------------------------------------------------------\n\n_last_lobby = {\"key\": None, \"sent\": 0.0}\n\n\ndef _name_of(entry):\n    for k in (\"gameName\", \"riotIdGameName\", \"summonerName\", \"displayName\"):\n        if entry.get(k):\n            return str(entry[k]).split(\"#\")[0]\n    return \"\"\n\n\ndef lobby_members(lcu):\n    \"\"\"Players in the current custom lobby, or None when not in one.\"\"\"\n    try:\n        lobby = lcu.get(\"/lol-lobby/v2/lobby\")\n    except (urllib.error.URLError, OSError, ValueError):\n        return None\n    cfg = (lobby or {}).get(\"gameConfig\") or {}\n    if not lobby or not cfg.get(\"isCustom\"):\n        return None\n    seen, out = set(), []\n    groups = [(100, cfg.get(\"customTeam100\") or []), (200, cfg.get(\"customTeam200\") or []),\n              (0, cfg.get(\"customSpectators\") or []), (0, lobby.get(\"members\") or [])]\n    for team, entries in groups:\n        for e in entries:\n            if not isinstance(e, dict) or e.get(\"isBot\") or e.get(\"botId\"):\n                continue\n            puuid = e.get(\"puuid\") or \"\"\n            key = puuid or _name_of(e)\n            if not key or key in seen:\n                continue\n            seen.add(key)\n            name, tag = _name_of(e), e.get(\"tagLine\") or e.get(\"riotIdTagLine\") or \"\"\n            if puuid and (not name or not tag):\n                try:\n                    who = lcu.get(\"/lol-summoner/v2/summoners/puuid/%s\" % puuid) or {}\n                    name, tag = who.get(\"gameName\") or name, who.get(\"tagLine\") or tag\n                except (urllib.error.URLError, OSError, ValueError):\n                    pass\n            if name:\n                out.append({\"puuid\": puuid or None, \"name\": name, \"tag\": tag or None, \"team\": team})\n    return out\n\n\ndef read_rank(lcu, puuid):\n    \"\"\"Solo queue rank for any player, read from the League client (no Riot API key needed).\"\"\"\n    if not puuid:\n        return None\n    try:\n        data = lcu.get(\"/lol-ranked/v1/ranked-stats/%s\" % puuid) or {}\n    except (urllib.error.URLError, OSError, ValueError):\n        return None\n    queues = data.get(\"queueMap\") or {q.get(\"queueType\"): q for q in (data.get(\"queues\") or []) if isinstance(q, dict)}\n\n    def pick(q):\n        tier = (q or {}).get(\"tier\") or \"\"\n        if tier and tier.upper() not in (\"NONE\", \"NA\", \"UNRANKED\"):\n            return tier.upper(), (q.get(\"division\") or \"\").upper(), int(q.get(\"leaguePoints\") or 0), q\n        return None\n\n    for key, source in ((\"RANKED_SOLO_5x5\", \"solo\"), (\"RANKED_FLEX_SR\", \"flex\")):\n        hit = pick(queues.get(key))\n        if hit:\n            tier, div, lp, q = hit\n            return {\"tier\": tier, \"division\": div if div not in (\"NA\", \"\") else \"\", \"lp\": lp,\n                    \"wins\": q.get(\"wins\"), \"losses\": q.get(\"losses\"), \"source\": source}\n    solo = queues.get(\"RANKED_SOLO_5x5\") or {}\n    prev = (solo.get(\"previousSeasonEndTier\") or data.get(\"highestPreviousSeasonEndTier\") or \"\").upper()\n    if prev and prev not in (\"NONE\", \"NA\", \"UNRANKED\"):\n        div = (solo.get(\"previousSeasonEndDivision\") or \"\").upper()\n        return {\"tier\": prev, \"division\": div if div != \"NA\" else \"\", \"lp\": 0, \"source\": \"last season\"}\n    return {\"tier\": \"\", \"division\": \"\", \"lp\": 0, \"source\": \"\"}\n\n\ndef send_ranks(cfg, lcu, puuids):\n    \"\"\"Reads and uploads ranks for a set of players (e.g. everyone in a game just uploaded).\"\"\"\n    ranks = {}\n    for p in list(puuids)[:30]:\n        r = read_rank(lcu, p)\n        if r is not None:\n            ranks[p] = r\n    if ranks:\n        post_json(cfg[\"site_url\"] + \"/api/ranks\", cfg[\"ingest_key\"], {\"ranks\": ranks})\n\n\ndef send_lobby(cfg, lcu, me):\n    \"\"\"Posts the lobby when it changes (and every few minutes while it lasts).\"\"\"\n    members = lobby_members(lcu)\n    if not members:\n        return\n    key = \",\".join(sorted(\"%s:%s\" % (m[\"name\"], m[\"team\"]) for m in members))\n    if key == _last_lobby[\"key\"] and time.time() - _last_lobby[\"sent\"] < 300:\n        return\n    for m in members:\n        m[\"rank\"] = read_rank(lcu, m.get(\"puuid\"))\n    status, _ = post_json(cfg[\"site_url\"] + \"/api/lobby\", cfg[\"ingest_key\"], {\"members\": members, \"uploader\": me})\n    if status == 200:\n        _last_lobby.update(key=key, sent=time.time())\n        log.info(\"Sent lobby to the site: %s\", \", \".join(m[\"name\"] for m in members))\n\n\ndef current_player(lcu):\n    try:\n        me = lcu.get(\"/lol-summoner/v1/current-summoner\") or {}\n        return {\"puuid\": me.get(\"puuid\"), \"gameName\": me.get(\"gameName\"),\n                \"tagLine\": me.get(\"tagLine\")}\n    except (urllib.error.URLError, OSError, ValueError):\n        return {}\n\n\n# --------------------------------------------------------------------------\n# Entry points\n# --------------------------------------------------------------------------\n\ndef run_test(cfg):\n    ok = True\n    print(\"custy.gg collector %s\\n\" % VERSION)\n    status, body = check_site(cfg)\n    if status == 200:\n        print(\"[ok]   Site reachable: %s (%s games stored)\" % (cfg[\"site_url\"], body.get(\"matches\", \"?\")))\n    elif status == 401:\n        print(\"[fail] Site is up, but ingest_key does not match INGEST_KEY\")\n        ok = False\n    else:\n        print(\"[fail] Could not reach %s/api/ingest (%s)\" % (cfg[\"site_url\"], body.get(\"error\") or \"HTTP %s\" % status))\n        ok = False\n\n    creds = find_client(cfg)\n    if not creds:\n        print(\"[fail] League client not found. Open League and log in, then run --test again.\")\n        return False\n    lcu = LeagueClient(*creds)\n    try:\n        me = current_player(lcu)\n        games = recent_games(lcu)\n    except (urllib.error.URLError, OSError, ValueError) as e:\n        print(\"[fail] Found the League client but could not read it: %s\" % e)\n        return False\n    name = \"%s#%s\" % (me.get(\"gameName\"), me.get(\"tagLine\"))\n    customs = [g for g in games if is_custom(g)]\n    print(\"[ok]   League client found, logged in as %s\" % name)\n    print(\"[ok]   %d recent games in history, %d of them custom games\" % (len(games), len(customs)))\n    return ok\n\n\ndef main():\n    args = set(sys.argv[1:])\n    if \"--selftest\" in args:\n        # Used by the build: proves the packaged app starts and can read attached settings.\n        out = sys.argv[sys.argv.index(\"--selftest\") + 1]\n        with open(out, \"w\", encoding=\"utf-8\") as f:\n            json.dump({\"version\": VERSION, \"frozen\": FROZEN, \"config\": embedded_config()}, f)\n        return\n    if FROZEN and platform.system() == \"Windows\" and \"--test\" not in args:\n        import windows_app  # installs, updates or removes the app; returns True to keep running here\n        if not windows_app.handle_launch(args):\n            return\n    handlers = [logging.FileHandler(LOG_PATH, encoding=\"utf-8\")]\n    if sys.stdout is not None:  # None when launched hidden with pythonw/pyw\n        handlers.append(logging.StreamHandler(sys.stdout))\n    logging.basicConfig(level=logging.INFO, handlers=handlers,\n                        format=\"%(asctime)s  %(message)s\", datefmt=\"%Y-%m-%d %H:%M:%S\")\n\n    cfg = load_config()\n    if \"--test\" in args:\n        sys.exit(0 if run_test(cfg) else 1)\n    if \"--review\" in args:\n        import review\n        review.serve_forever(cfg)\n        return\n\n    log.info(\"custy.gg collector %s started, uploading to %s\", VERSION, cfg[\"site_url\"])\n    if FROZEN and platform.system() == \"Windows\":\n        import windows_app\n        windows_app.run_with_tray(cfg, lambda stop: run_collector(cfg, args, stop))\n    else:\n        run_collector(cfg, args)\n\n\n# What the tray icon shows. Updated by the collector loop.\nSTATUS = {\"state\": \"Starting\", \"uploaded\": 0, \"last_upload\": None, \"paused\": False, \"on_upload\": None}\n\n\ndef run_collector(cfg, args, stop=None):\n    \"\"\"Checks for new custom games until `stop` (a threading.Event) is set.\"\"\"\n    def wait(seconds):\n        if stop is None:\n            time.sleep(seconds)\n            return False\n        return stop.wait(seconds)\n\n    seen = set() if \"--all\" in args else load_state()\n    force = \"--all\" in args\n    last_phase = None\n    waiting_logged = False\n    while not (stop and stop.is_set()):\n        try:\n            if STATUS[\"paused\"]:\n                STATUS[\"state\"] = \"Paused\"\n                if wait(5):\n                    return\n                continue\n            creds = find_client(cfg)\n            if not creds:\n                STATUS[\"state\"] = \"Waiting for League to open\"\n                if \"--once\" in args:\n                    log.info(\"League client is not running. Open League, then try again.\")\n                    return\n                if not waiting_logged:\n                    log.info(\"Waiting for the League client to open...\")\n                    waiting_logged = True\n                if wait(POLL_SECONDS):\n                    return\n                continue\n            waiting_logged = False\n            lcu = LeagueClient(*creds)\n\n            try:\n                phase = lcu.get(\"/lol-gameflow/v1/gameflow-phase\")\n            except (urllib.error.URLError, OSError, ValueError):\n                phase = None\n\n            if phase in (\"InProgress\", \"Reconnect\", \"GameStart\") and \"--once\" not in args:\n                # Mid-game: nothing new to upload until it ends.\n                STATUS[\"state\"] = \"In a game\"\n                last_phase = phase\n                if wait(30):\n                    return\n                continue\n\n            if phase in (\"PreEndOfGame\", \"EndOfGame\", \"WaitingForStats\") and last_phase != phase:\n                STATUS[\"state\"] = \"Game ended, checking for it\"\n                if wait(AFTER_GAME_DELAY):  # give match history a moment to update\n                    return\n            last_phase = phase\n\n            STATUS[\"state\"] = \"Watching for custom games\"\n            me = current_player(lcu)\n            in_lobby = phase in (\"Lobby\", \"ChampSelect\")\n            if in_lobby:\n                STATUS[\"state\"] = \"In a lobby\"\n                try:\n                    send_lobby(cfg, lcu, me)\n                except Exception as e:\n                    log.warning(\"Couldn't send the lobby: %s\", e)\n            n = sync(cfg, lcu, seen, me, force=force)\n            if n:\n                STATUS[\"uploaded\"] += n\n                STATUS[\"last_upload\"] = time.time()\n                if STATUS[\"on_upload\"]:\n                    try:\n                        STATUS[\"on_upload\"](n)\n                    except Exception:\n                        pass\n            force = False\n            if \"--once\" in args:\n                return\n            if in_lobby:\n                if wait(15):  # check the lobby more often so the roster stays current\n                    return\n                continue\n        except SystemExit as e:\n            if stop is None:\n                raise\n            STATUS[\"state\"] = \"Stopped: %s\" % e\n            log.error(\"%s\", e)\n            return\n        except Exception as e:  # keep running through client restarts and network blips\n            STATUS[\"state\"] = \"Couldn't reach League, retrying\"\n            log.warning(\"Check failed: %s\", e)\n            if \"--once\" in args:\n                return\n        if wait(POLL_SECONDS):\n            return\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except KeyboardInterrupt:\n        pass\n",
  "mac-autostart-off.sh": "#!/bin/bash\nPLIST=\"$HOME/Library/LaunchAgents/gg.custy.collector.plist\"\nlaunchctl unload \"$PLIST\" 2>/dev/null || true\nrm -f \"$PLIST\"\necho \"Autostart removed and collector stopped.\"\n",
  "mac-autostart-on.sh": "#!/bin/bash\n# Starts the collector in the background at every login on macOS, and starts it now.\nset -e\nDIR=\"$(cd \"$(dirname \"$0\")\" && pwd)\"\nPY=\"$(command -v python3)\"\nPLIST=\"$HOME/Library/LaunchAgents/gg.custy.collector.plist\"\n[ -f \"$DIR/config.json\" ] || { echo \"config.json is missing. Copy config.example.json to config.json and fill it in first.\"; exit 1; }\nmkdir -p \"$HOME/Library/LaunchAgents\"\ncat > \"$PLIST\" <<EOF\n<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n<plist version=\"1.0\"><dict>\n  <key>Label</key><string>gg.custy.collector</string>\n  <key>ProgramArguments</key><array><string>$PY</string><string>$DIR/custy_collector.py</string></array>\n  <key>RunAtLoad</key><true/>\n  <key>KeepAlive</key><true/>\n  <key>StandardOutPath</key><string>/dev/null</string>\n  <key>StandardErrorPath</key><string>/dev/null</string>\n</dict></plist>\nEOF\nlaunchctl unload \"$PLIST\" 2>/dev/null || true\nlaunchctl load \"$PLIST\"\necho \"Done. The collector runs in the background at login. Activity goes to $DIR/collector.log\"\n",
  "review.html": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>custy.gg game review</title>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<style>\n:root {\n  --night:#0d1424; --deck:#141d31; --deck-2:#1a2540; --line:#253150; --line-soft:#1d2843;\n  --ink:#e6ebf5; --mute:#8f9ab4; --faint:#5d6987;\n  --blue:#4f9dff; --blue-ink:#9cc8ff; --blue-wash:rgba(79,157,255,.11);\n  --red:#f2596b; --red-ink:#ff9aa6; --red-wash:rgba(242,89,107,.1);\n  --gold:#e3b866; --gold-wash:rgba(227,184,102,.12);\n  color-scheme: dark;\n}\n* { box-sizing: border-box; }\nbody { margin:0; background:var(--night); color:var(--ink); font:15px/1.5 \"Segoe UI\", system-ui, sans-serif; }\nheader { display:flex; align-items:baseline; gap:12px; padding:14px 22px; border-bottom:1px solid var(--line-soft); }\nheader b { font-size:18px; letter-spacing:.3px; } header b span { color:var(--gold); }\nheader .tag { font-size:11px; text-transform:uppercase; letter-spacing:1px; color:var(--night); background:var(--gold); padding:1px 7px; border-radius:4px; }\nheader button { margin-left:4px; }\nheader .who { margin-left:auto; color:var(--mute); font-size:13px; }\nmain { display:grid; grid-template-columns: 300px 1fr; min-height: calc(100vh - 54px); }\naside { border-right:1px solid var(--line-soft); overflow-y:auto; max-height: calc(100vh - 54px); }\n.filter { display:flex; gap:6px; padding:10px 14px; border-bottom:1px solid var(--line-soft); flex-wrap:wrap; }\n.filter button { padding:3px 10px; border-radius:20px; font-size:12px; }\n.filter button.on { background:var(--blue); border-color:var(--blue); color:#06101f; font-weight:600; }\naside .note { padding:10px 14px; color:var(--mute); font-size:13px; border-bottom:1px solid var(--line-soft); }\n.game { display:flex; gap:10px; align-items:center; padding:9px 14px; border-left:3px solid transparent; cursor:pointer; border-bottom:1px solid var(--line-soft); }\n.game:hover { background:var(--deck); }\n.game.on { background:var(--deck-2); }\n.game.w { border-left-color:var(--blue); } .game.l { border-left-color:var(--red); }\n.game img { width:38px; height:38px; border-radius:6px; }\n.game .t { font-size:13px; line-height:1.35; } .game .t small { color:var(--mute); display:block; }\n.game .kda { margin-left:auto; text-align:right; font-size:13px; } .game .kda small { color:var(--faint); display:block; }\nsection { padding:22px 28px; max-width:1100px; }\nh1 { font-size:22px; margin:0 0 2px; } h2 { font-size:15px; margin:26px 0 10px; color:var(--mute); text-transform:uppercase; letter-spacing:.8px; font-weight:600; }\n.sub { color:var(--mute); font-size:13px; }\n.vs { display:flex; align-items:center; gap:12px; }\n.vs { margin-bottom:12px; } .yt { display:inline-block; }\n.vs img { width:52px; height:52px; border-radius:8px; }\n.win { color:var(--blue-ink); } .loss { color:var(--red-ink); }\n.card { background:var(--deck); border:1px solid var(--line-soft); border-radius:12px; padding:14px 16px; }\n.banner { background:var(--gold-wash); border:1px solid rgba(227,184,102,.35); border-radius:10px; padding:10px 14px; margin-top:14px; font-size:14px; display:flex; gap:12px; align-items:center; }\n.banner button { margin-left:auto; }\nbutton, .btn { font:inherit; font-size:13px; background:var(--deck-2); color:var(--ink); border:1px solid var(--line); border-radius:8px; padding:6px 12px; cursor:pointer; text-decoration:none; white-space:nowrap; }\nbutton:hover, .btn:hover { border-color:var(--blue); }\nbutton.primary { background:var(--blue); border-color:var(--blue); color:#06101f; font-weight:600; }\nbutton:disabled { opacity:.5; cursor:default; }\nsvg text { fill:var(--mute); font-size:11px; }\n.moment { display:grid; grid-template-columns: 120px 1fr auto; gap:16px; align-items:start; padding:14px 0; border-top:1px solid var(--line-soft); }\n.moment:first-child { border-top:0; }\n.moment .when { font-weight:600; font-size:16px; } .moment .when small { display:block; color:var(--red-ink); font-weight:400; font-size:12px; }\n.moment .part { margin-bottom:6px; } .moment .part > b { display:block; }\n.moment ul { margin:8px 0 0; padding-left:18px; color:var(--mute); font-size:13px; }\n.moment .cmp { font-size:13px; color:var(--mute); } .moment .cmp b { color:var(--ink); font-weight:600; }\n.moment .acts { display:flex; flex-direction:column; gap:6px; }\n.timings { display:grid; grid-template-columns: repeat(auto-fill, minmax(150px,1fr)); gap:10px; }\n.timings .card { padding:10px 12px; } .timings .k { color:var(--mute); font-size:12px; } .timings .v { font-size:18px; font-weight:600; }\n.timings .d { font-size:12px; color:var(--faint); }\n.bad { color:var(--red-ink) !important; } .good { color:var(--blue-ink) !important; }\n.toast { position:fixed; right:18px; bottom:18px; background:var(--deck-2); border:1px solid var(--line); border-radius:10px; padding:10px 14px; max-width:420px; font-size:14px; box-shadow:0 8px 30px rgba(0,0,0,.4); display:none; }\n.empty { color:var(--mute); padding:40px 0; }\n.tabs { display:flex; gap:6px; margin-top:18px; border-bottom:1px solid var(--line-soft); }\n.tabs button { border:0; border-bottom:2px solid transparent; border-radius:0; background:none; padding:8px 14px; font-size:14px; color:var(--mute); }\n.tabs button.on { color:var(--ink); border-bottom-color:var(--gold); }\ntable.grid { width:100%; border-collapse:collapse; font-size:13px; }\ntable.grid th { text-align:left; color:var(--mute); font-weight:600; padding:6px 8px; border-bottom:1px solid var(--line); }\ntable.grid td { padding:8px; border-bottom:1px solid var(--line-soft); vertical-align:top; }\ntable.grid td .y { font-size:15px; font-weight:600; } table.grid td .e { color:var(--faint); font-size:12px; display:block; }\n.finding { padding:10px 0; border-top:1px solid var(--line-soft); } .finding:first-child { border-top:0; }\n.finding b { display:block; } .finding span { color:var(--mute); font-size:13px; }\n.seg { display:inline-flex; gap:4px; margin-bottom:8px; } .seg button { padding:3px 10px; font-size:12px; border-radius:20px; }\n.seg button.on { background:var(--blue); border-color:var(--blue); color:#06101f; font-weight:600; }\n.legend { display:flex; gap:16px; font-size:12px; color:var(--mute); margin-top:6px; }\n.legend i { display:inline-block; width:12px; height:8px; border-radius:2px; margin-right:5px; vertical-align:middle; }\n</style>\n</head>\n<body>\n<header><b>custy<span>.gg</span> game review</b><span class=\"tag\">test</span><span class=\"who\" id=\"who\"></span><button id=\"refresh\" title=\"Look for new games\">↻ Refresh</button></header>\n<main>\n  <aside id=\"list\"><div class=\"note\">Reading your games from League...</div></aside>\n  <section id=\"view\"><div class=\"empty\">Pick a game on the left.</div></section>\n</main>\n<div class=\"toast\" id=\"toast\"></div>\n<script>\nconst KEY = new URLSearchParams(location.search).get(\"k\") || \"\";\nconst api = (path, opt = {}) => fetch(path, { ...opt, headers: { \"X-Custy-Key\": KEY } }).then(async r => {\n  const body = await r.json().catch(() => ({}));\n  if (!r.ok) throw new Error(body.error || (\"HTTP \" + r.status));\n  return body;\n});\nconst $ = (id) => document.getElementById(id);\nconst esc = (s) => String(s ?? \"\").replace(/[&<>\"]/g, c => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\" }[c]));\nconst clock = (t) => { t = Math.max(0, Math.round(t)); return Math.floor(t / 60) + \":\" + String(t % 60).padStart(2, \"0\"); };\nconst signed = (n) => (n > 0 ? \"+\" : n < 0 ? \"−\" : \"\") + Math.abs(Math.round(n)).toLocaleString();\nconst ROLE_NAME = { TOP: \"Top\", JUNGLE: \"Jungle\", MID: \"Mid\", BOT: \"Bot\", SUPPORT: \"Support\" };\n\n// ---------------------------------------------------------------- Data Dragon (names, icons, item costs)\nconst DD = { v: null, champ: {}, items: {} };\nasync function loadDD() {\n  try {\n    DD.v = (await (await fetch(\"https://ddragon.leagueoflegends.com/api/versions.json\")).json())[0];\n    const ch = await (await fetch(`https://ddragon.leagueoflegends.com/cdn/${DD.v}/data/en_US/champion.json`)).json();\n    for (const c of Object.values(ch.data)) DD.champ[c.key] = { name: c.name, id: c.id };\n    const it = await (await fetch(`https://ddragon.leagueoflegends.com/cdn/${DD.v}/data/en_US/item.json`)).json();\n    DD.items = it.data;\n  } catch (e) { console.warn(\"Data Dragon unavailable\", e); }\n}\nconst champName = (id) => DD.champ[id]?.name || (\"Champion \" + id);\nconst champIcon = (id) => DD.champ[id] ? `https://ddragon.leagueoflegends.com/cdn/${DD.v}/img/champion/${DD.champ[id].id}.png` : \"\";\nconst itemName = (id) => DD.items[id]?.name || (\"item \" + id);\nconst itemCost = (id) => DD.items[id]?.gold?.total || 0;\nconst isBoots = (id) => { const it = DD.items[id]; return !!it && (it.tags || []).includes(\"Boots\") && it.gold.total >= 700 && id != 1001; };\nconst isCompleted = (id) => { const it = DD.items[id]; return !!it && it.gold.total >= 2200 && !(it.into || []).length && !(it.tags || []).includes(\"Consumable\") && !isBoots(id); };\n\n// ---------------------------------------------------------------- Map areas\nfunction area(x, y) {\n  if (x == null) return \"\";\n  if (x < 3600 && y < 3600) return \"blue base\";\n  if (x > 11300 && y > 11300) return \"red base\";\n  if (x < 2300 || y > 12600) return \"top lane\";\n  if (y < 2300 || x > 12600) return \"bot lane\";\n  if (Math.abs(x - y) < 1300) return \"mid lane\";\n  if (Math.abs(x + y - 14800) < 1500) return y > x ? \"top river\" : \"bot river\";\n  return y > x ? \"top-side jungle\" : \"bot-side jungle\";\n}\nconst dist = (a, b) => (a && b) ? Math.hypot(a.x - b.x, a.y - b.y) : Infinity;\n\n// ---------------------------------------------------------------- Turning one game into series and events\nfunction analyse(data) {\n  const g = data.game, frames = data.timeline?.frames || [];\n  const ids = {}; for (const i of g.participantIdentities || []) ids[i.participantId] = i.player || {};\n  const parts = g.participants || [];\n  const me = parts.find(p => ids[p.participantId]?.puuid === data.me);\n  if (!me || frames.length < 3) return null;\n  const role = data.roles[me.participantId] || \"\";\n  const opp = parts.find(p => p.teamId !== me.teamId && data.roles[p.participantId] === role) || null;\n  const enemyJg = parts.find(p => p.teamId !== me.teamId && data.roles[p.participantId] === \"JUNGLE\") || null;\n  const pf = (f, pid) => f.participantFrames?.[String(pid)] || {};\n  const series = (pid, fn) => frames.map(f => fn(pf(f, pid)));\n  const gold = (pid) => series(pid, x => x.totalGold || 0);\n  const cs = (pid) => series(pid, x => (x.minionsKilled || 0) + (x.jungleMinionsKilled || 0));\n  const myGold = gold(me.participantId), oppGold = opp ? gold(opp.participantId) : null;\n  const diff = oppGold ? myGold.map((v, i) => v - oppGold[i]) : null;\n  const events = frames.flatMap(f => f.events || []).sort((a, b) => a.timestamp - b.timestamp);\n  const champOf = (pid) => champName(parts.find(p => p.participantId === pid)?.championId);\n\n  // Purchases (undos removed), grouped into backs.\n  const buys = {};\n  for (const e of events) {\n    if (e.type === \"ITEM_PURCHASED\") (buys[e.participantId] ??= []).push({ t: e.timestamp / 1000, id: e.itemId });\n    if (e.type === \"ITEM_UNDO\") { const l = buys[e.participantId] || []; const u = e.beforeId || e.itemId;\n      for (let i = l.length - 1; i >= 0; i--) if (l[i].id === u) { l.splice(i, 1); break; } }\n  }\n  const backsOf = (pid) => {\n    const out = [];\n    for (const b of (buys[pid] || []).filter(b => b.t > 120)) {\n      const last = out[out.length - 1];\n      if (last && b.t - last.end < 40) { last.items.push(b.id); last.end = b.t; }\n      else out.push({ t: b.t, end: b.t, items: [b.id] });\n    }\n    for (const b of out) b.spent = b.items.reduce((a, id) => a + itemCost(id), 0);\n    return out;\n  };\n  const firstOf = (pid, test) => (buys[pid] || []).find(b => test(b.id))?.t ?? null;\n  const lvl6 = (pid) => {\n    const e = events.find(e => e.type === \"SKILL_LEVEL_UP\" && e.participantId === pid && e.skillSlot === 4);\n    if (e) return e.timestamp / 1000;\n    const m = frames.findIndex(f => (pf(f, pid).level || 0) >= 6);\n    return m >= 0 ? m * 60 : null;\n  };\n  const kills = events.filter(e => e.type === \"CHAMPION_KILL\");\n  const myCs = cs(me.participantId);\n  const xp = (pid) => series(pid, x => x.xp || 0), lvl = (pid) => series(pid, x => x.level || 0);\n  const myXp = xp(me.participantId), oppXp = opp ? xp(opp.participantId) : null;\n  const completed = (buys[me.participantId] || []).filter(b => isCompleted(b.id));\n  const STAT = (i, k) => DD.items[i]?.stats?.[k] || 0;\n  const defense = (k) => parts.filter(p => p.teamId !== me.teamId).filter(p =>\n    [0, 1, 2, 3, 4, 5].reduce((a, n) => a + STAT(p.stats?.[\"item\" + n], k), 0) >= 80).length;\n  return {\n    g, me, opp, enemyJg, role, frames, events, kills, champOf, pf,\n    minutes: frames.length - 1,\n    myGold, oppGold, diff, myCs,\n    oppCs: opp ? cs(opp.participantId) : null,\n    xp: myXp, level: lvl(me.participantId), xpdiff: oppXp ? myXp.map((v, i) => v - oppXp[i]) : null,\n    csdiff: opp ? myCs.map((v, i) => v - cs(opp.participantId)[i]) : null,\n    items: completed, armorN: defense(\"FlatArmorMod\"), mrN: defense(\"FlatSpellBlockMod\"),\n    backs: backsOf(me.participantId), oppBacks: opp ? backsOf(opp.participantId) : [],\n    firstItem: firstOf(me.participantId, isCompleted),\n    lvl6: lvl6(me.participantId), oppLvl6: opp ? lvl6(opp.participantId) : null,\n    deaths: kills.filter(e => e.victimId === me.participantId).map(e => ({ t: e.timestamp / 1000, e })),\n    platesLost: events.filter(e => e.type === \"TURRET_PLATE_DESTROYED\" && e.teamId === me.teamId && e.timestamp < 14 * 60000 &&\n      laneMatches(e.laneType, role)).map(e => e.timestamp / 1000),\n  };\n}\nfunction laneMatches(lane, role) {\n  lane = String(lane || \"\");\n  return (role === \"TOP\" && lane.startsWith(\"TOP\")) || (role === \"MID\" && lane.startsWith(\"MID\")) ||\n         ((role === \"BOT\" || role === \"SUPPORT\") && lane.startsWith(\"BOT\"));\n}\n\n// ---------------------------------------------------------------- \"Your usual\": your other games on this champion (or role)\nfunction pct(values, q) {\n  const v = values.filter(x => x != null && Number.isFinite(x)).sort((a, b) => a - b);\n  if (!v.length) return null;\n  const i = (v.length - 1) * q, lo = Math.floor(i), hi = Math.ceil(i);\n  return v[lo] + (v[hi] - v[lo]) * (i - lo);\n}\nfunction baseline(list) {\n  if (list.length < 3) return null;\n  const maxM = Math.max(...list.map(a => a.minutes));\n  const band = (pick) => Array.from({ length: maxM + 1 }, (_, m) => {\n    const vals = list.map(a => pick(a)?.[m]).filter(v => v != null);\n    return vals.length >= 3 ? { p25: pct(vals, .25), p50: pct(vals, .5), p75: pct(vals, .75) } : null;\n  });\n  const med = (fn) => pct(list.map(fn), .5);\n  return {\n    n: list.length,\n    diff: band(a => a.diff), gold: band(a => a.myGold), cs: band(a => a.myCs),\n    firstBack: med(a => a.backs[0]?.t), firstBackGold: med(a => a.backs[0]?.spent),\n    firstItem: med(a => a.firstItem),\n    lvl6Gap: med(a => a.lvl6 != null && a.oppLvl6 != null ? a.lvl6 - a.oppLvl6 : null),\n    deaths14: med(a => a.deaths.filter(d => d.t < 840).length),\n  };\n}\n\n// ---------------------------------------------------------------- Finding the moments\nfunction findMoments(A, B) {\n  const out = [];\n  const curve = A.diff || A.myGold, useDiff = !!A.diff;\n  const band = B ? (useDiff ? B.diff : B.gold) : null;\n  const last = Math.min(A.minutes, 25);\n\n  // 1. Lane gold: dropped 400+ within 3 minutes and ended below your usual middle half.\n  if (useDiff) {\n    let cur = null;\n    for (let m = 2; m <= last; m++) {\n      const lo = Math.max(0, m - 3);\n      let peak = lo; for (let k = lo; k < m; k++) if (curve[k] > curve[peak]) peak = k;\n      const drop = curve[peak] - curve[m];\n      const below = band?.[m] ? curve[m] < band[m].p25 : true;\n      if (drop >= 400 && below) {\n        if (cur && peak <= cur.endM) { cur.endM = m; }\n        else { cur = { kind: \"gold\", peakM: peak, endM: m }; out.push(cur); }\n      }\n    }\n    for (const w of out) {\n      // Keep the window going while the gap keeps opening.\n      while (w.endM < A.minutes && curve[w.endM + 1] < curve[w.endM]) w.endM++;\n      const low = Math.min(...curve.slice(w.peakM, w.endM + 1));\n      w.cost = curve[w.peakM] - low;\n      w.start = Math.max(0, w.peakM * 60 - 45); w.end = w.endM * 60;\n      w.title = `Lane gold went from ${signed(curve[w.peakM])} to ${signed(low)}`;\n      const b = band?.[w.endM];\n      w.compare = b ? `Your usual at ${w.endM}:00 is <b>${signed(b.p50)}</b> (middle half ${signed(b.p25)} to ${signed(b.p75)}).`\n                    : `Lost ${Math.round(w.cost).toLocaleString()} gold to your lane opponent in ${w.endM - w.peakM} min.`;\n    }\n  }\n\n  // 2. Deaths: any before 14:00, and any after which your lane gold fell 300+.\n  for (const d of A.deaths) {\n    const m0 = Math.floor(d.t / 60), m2 = Math.min(A.minutes, m0 + 2);\n    const swing = useDiff ? curve[m0] - curve[m2] : 0;\n    if (d.t >= 840 && swing < 300) continue;\n    const inside = out.find(w => w.kind === \"gold\" && d.t >= w.start && d.t <= w.end + 30);\n    if (inside) continue; // already covered by a gold moment (it'll be listed there)\n    const killers = [d.e.killerId, ...(d.e.assistingParticipantIds || [])].filter(p => p > 0).map(A.champOf);\n    out.push({\n      kind: \"death\", start: Math.max(0, d.t - 45), end: d.t + 10, cost: Math.max(300, swing),\n      title: `You died at ${clock(d.t)}${killers.length ? \" to \" + killers.join(\" + \") : \"\"}`,\n      compare: d.t >= 840 ? `Your lane gold went from ${signed(curve[m0])} to ${signed(curve[m2])} over the next 2 minutes.`\n        : B ? `In your usual game you die <b>${Math.round(B.deaths14 ?? 0)}</b> time${Math.round(B.deaths14 ?? 0) === 1 ? \"\" : \"s\"} before 14:00.` : \"Deaths before 14:00 usually decide the lane.\",\n    });\n  }\n\n  // 3. CS at 10 and 14 minutes.\n  if (A.role !== \"SUPPORT\") {\n    const target = (m) => B?.cs?.[m]?.p50 ?? ({ JUNGLE: 5.5, TOP: 7, MID: 7, BOT: 7.5 }[A.role] || 7) * m;\n    for (const m of [10, 14]) {\n      if (A.minutes < m) continue;\n      const gap = target(m) - A.myCs[m];\n      if (gap < 10) continue;\n      if (out.some(w => w.kind === \"cs\")) { const w = out.find(w => w.kind === \"cs\"); w.cost = Math.max(w.cost, gap * 20); w.end = m * 60; w.title = `${A.myCs[m]} CS at ${m}:00, ${Math.round(gap)} under`; continue; }\n      out.push({ kind: \"cs\", start: (m - 4) * 60, end: m * 60, cost: gap * 20,\n        title: `${A.myCs[m]} CS at ${m}:00, ${Math.round(gap)} under`,\n        compare: B?.cs?.[m] ? `Your usual: <b>${Math.round(B.cs[m].p50)}</b> at ${m}:00.` : `Rough target for ${ROLE_NAME[A.role] || \"your role\"}: <b>${Math.round(target(m))}</b>.` });\n    }\n  }\n\n  // 4. First back.\n  const fb = A.backs[0];\n  if (B?.firstBack && fb && fb.t - B.firstBack >= 60) {\n    out.push({ kind: \"back\", start: Math.max(0, B.firstBack - 45), end: fb.t + 5, cost: (fb.t - B.firstBack) * 4,\n      title: `First back at ${clock(fb.t)} with ${fb.spent.toLocaleString()} gold spent`,\n      compare: `Your usual: back by <b>${clock(B.firstBack)}</b>, spending ~${Math.round(B.firstBackGold || 0).toLocaleString()}.` });\n  }\n\n  // 5. First completed item.\n  for (const [k, label] of [[\"firstItem\", \"First item\"]]) {\n    if (B?.[k] && A[k] && A[k] - B[k] >= 90) {\n      out.push({ kind: k, start: Math.max(0, B[k] - 45), end: A[k] + 5, cost: (A[k] - B[k]) * 3,\n        title: `${label} finished at ${clock(A[k])}`, compare: `Your usual: <b>${clock(B[k])}</b>.` });\n    }\n  }\n\n  // 6. Level 6 behind your lane opponent.\n  if (A.lvl6 != null && A.oppLvl6 != null && A.lvl6 - A.oppLvl6 > 20 && A.role !== \"JUNGLE\") {\n    const gap = A.lvl6 - A.oppLvl6;\n    out.push({ kind: \"lvl6\", start: Math.max(0, A.oppLvl6 - 30), end: A.lvl6 + 15, cost: 150 + gap * 3,\n      title: `${A.opp ? champName(A.opp.championId) : \"Your opponent\"} hit 6 ${Math.round(gap)}s before you`,\n      compare: B?.lvl6Gap != null ? `Your usual: <b>${B.lvl6Gap <= 0 ? Math.round(-B.lvl6Gap) + \"s ahead\" : Math.round(B.lvl6Gap) + \"s behind\"}</b>.` : \"Being second to 6 is a window to play safe.\" });\n  }\n\n  // 7. Plates lost before 14:00.\n  if (A.platesLost.length >= 2) {\n    out.push({ kind: \"plates\", start: Math.max(0, A.platesLost[0] - 45), end: A.platesLost[A.platesLost.length - 1] + 5,\n      cost: A.platesLost.length * 160, title: `${A.platesLost.length} plates lost before 14:00`, compare: \"\" });\n  }\n\n  // Overlapping findings become one moment to watch.\n  const merged = [];\n  for (const w of out.filter(w => w.cost > 0).sort((a, b) => a.start - b.start)) {\n    const cur = merged[merged.length - 1];\n    if (cur && w.start <= cur.end) { cur.end = Math.max(cur.end, w.end); cur.cost += w.cost; cur.parts.push(w); }\n    else merged.push({ start: w.start, end: w.end, cost: w.cost, parts: [w] });\n  }\n  for (const m of merged) { m.parts.sort((a, b) => a.start - b.start); m.context = context(A, m); }\n  // Keep the ones that cost the most, then list them in the order they happened.\n  return merged.sort((a, b) => b.cost - a.cost).slice(0, 6).sort((a, b) => a.start - b.start);\n}\n\nfunction context(A, w) {\n  const lines = [], inWin = (t) => t >= w.start - 5 && t <= w.end + 30;\n  const add = (t, html) => lines.push({ t, html });\n  for (const k of A.kills) {\n    const t = k.timestamp / 1000; if (!inWin(t)) continue;\n    const killer = k.killerId > 0 ? A.champOf(k.killerId) : \"an execution\";\n    const helpers = (k.assistingParticipantIds || []).map(A.champOf);\n    const where = area(k.position?.x, k.position?.y);\n    if (k.victimId === A.me.participantId) add(t, `${clock(t)} you died to ${killer}${helpers.length ? \" + \" + helpers.join(\" + \") : \"\"}${where ? \" (\" + where + \")\" : \"\"}`);\n    else if (k.killerId === A.me.participantId) add(t, `${clock(t)} you killed ${A.champOf(k.victimId)}${where ? \" (\" + where + \")\" : \"\"}`);\n    else if (A.opp && k.victimId === A.opp.participantId) add(t, `${clock(t)} ${A.champOf(k.victimId)} died to ${killer}`);\n    else if (A.opp && k.killerId === A.opp.participantId) add(t, `${clock(t)} ${A.champOf(k.killerId)} killed ${A.champOf(k.victimId)}`);\n  }\n  if (A.enemyJg) {\n    for (let m = Math.ceil(w.start / 60); m <= Math.floor(w.end / 60) && m <= A.minutes; m++) {\n      const jp = A.pf(A.frames[m], A.enemyJg.participantId).position, mp = A.pf(A.frames[m], A.me.participantId).position;\n      if (!jp) continue;\n      if (dist(jp, mp) < 2600) add(m * 60, `${m}:00 enemy jungler (${champName(A.enemyJg.championId)}) <b>near you</b> in ${area(jp.x, jp.y)}`);\n    }\n  }\n  for (const b of A.backs) if (inWin(b.t)) add(b.t, `${clock(b.t)} you bought ${describeBuy(b)}`);\n  for (const b of A.oppBacks) if (inWin(b.t)) add(b.t, `${clock(b.t)} ${champName(A.opp.championId)} bought ${describeBuy(b)}`);\n  for (const e of A.events) {\n    const t = e.timestamp / 1000; if (!inWin(t)) continue;\n    if (e.type === \"ELITE_MONSTER_KILL\") add(t, `${clock(t)} ${String(e.monsterType || \"\").replace(/_/g, \" \").toLowerCase()} taken by ${teamOf(A, e.killerId)}`);\n  }\n  return lines.sort((a, b) => a.t - b.t).map(l => l.html).slice(0, 10);\n}\nconst teamOf = (A, pid) => (A.g.participants.find(p => p.participantId === pid)?.teamId === A.me.teamId ? \"your team\" : \"the enemy\");\nfunction describeBuy(b) {\n  const main = b.items.slice().sort((x, y) => itemCost(y) - itemCost(x)).slice(0, 2).map(itemName);\n  return `${main.join(\", \")}${b.items.length > 2 ? \" +\" + (b.items.length - 2) : \"\"} (${b.spent.toLocaleString()}g)`;\n}\n\n// ---------------------------------------------------------------- Chart\nfunction chart(A, B, moments) {\n  const W = 1000, H = 260, L = 50, R = 12, T = 14, Bm = 26;\n  const curve = A.diff || A.myGold, band = B ? (A.diff ? B.diff : B.gold) : null;\n  const n = A.minutes;\n  let lo = Math.min(0, ...curve), hi = Math.max(0, ...curve);\n  if (band) for (const b of band.slice(0, n + 1)) if (b) { lo = Math.min(lo, b.p25); hi = Math.max(hi, b.p75); }\n  const pad = (hi - lo) * .08 || 500; lo -= pad; hi += pad;\n  const x = (m) => L + (m / n) * (W - L - R), y = (v) => T + (hi - v) / (hi - lo) * (H - T - Bm);\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" width=\"100%\" role=\"img\" aria-label=\"Lane gold difference by minute\">`;\n  for (const w of moments) s += `<rect x=\"${x(w.start / 60)}\" y=\"${T}\" width=\"${Math.max(3, x(w.end / 60) - x(w.start / 60))}\" height=\"${H - T - Bm}\" fill=\"var(--red-wash)\"/>`;\n  const step = (hi - lo) > 6000 ? 2000 : (hi - lo) > 2500 ? 1000 : 500;\n  for (let v = Math.ceil(lo / step) * step; v <= hi; v += step)\n    s += `<line x1=\"${L}\" x2=\"${W - R}\" y1=\"${y(v)}\" y2=\"${y(v)}\" stroke=\"${v === 0 ? \"var(--line)\" : \"var(--line-soft)\"}\"/><text x=\"${L - 6}\" y=\"${y(v) + 4}\" text-anchor=\"end\">${signed(v)}</text>`;\n  for (let m = 0; m <= n; m += 5) s += `<text x=\"${x(m)}\" y=\"${H - 8}\" text-anchor=\"middle\">${m}:00</text>`;\n  if (band) {\n    const pts = band.slice(0, n + 1).map((b, m) => b && [m, b]).filter(Boolean);\n    if (pts.length > 1) {\n      s += `<path d=\"M${pts.map(([m, b]) => x(m) + \",\" + y(b.p75)).join(\"L\")}L${pts.slice().reverse().map(([m, b]) => x(m) + \",\" + y(b.p25)).join(\"L\")}Z\" fill=\"var(--blue-wash)\" stroke=\"none\"/>`;\n      s += `<path d=\"M${pts.map(([m, b]) => x(m) + \",\" + y(b.p50)).join(\"L\")}\" fill=\"none\" stroke=\"var(--blue)\" stroke-opacity=\".45\" stroke-dasharray=\"4 4\"/>`;\n    }\n  }\n  s += `<path d=\"M${curve.map((v, m) => x(m) + \",\" + y(v)).join(\"L\")}\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"2.5\"/>`;\n  curve.forEach((v, m) => s += `<circle cx=\"${x(m)}\" cy=\"${y(v)}\" r=\"6\" fill=\"transparent\"><title>${m}:00  ${signed(v)}</title></circle>`);\n  for (const d of A.deaths) { const m = d.t / 60, i = Math.min(n, Math.round(m));\n    s += `<text x=\"${x(m)}\" y=\"${y(curve[i]) - 9}\" text-anchor=\"middle\" style=\"fill:var(--red-ink);font-size:13px\">✕</text>`; }\n  return s + \"</svg>\";\n}\n\n// ---------------------------------------------------------------- Page\nlet STATE = { games: [], me: null, replayApi: null, current: null, queue: \"all\" };\nconst QUEUE_FILTERS = [[\"all\", \"All\"], [\"solo\", \"Solo/Duo\"], [\"flex\", \"Flex\"], [\"other\", \"Normals & other\"]];\nconst queueGroup = (q) => q === \"Ranked Solo/Duo\" ? \"solo\" : q === \"Ranked Flex\" ? \"flex\" : \"other\";\nconst cacheGame = {};\nconst getGame = async (id) => cacheGame[id] ??= api(\"/api/game/\" + id);\n\nasync function loadList() {\n  const btn = $(\"refresh\"); btn.disabled = true; btn.textContent = \"Refreshing...\";\n  let r;\n  try { r = await api(\"/api/games\"); } finally { btn.disabled = false; btn.textContent = \"↻ Refresh\"; }\n  const before = new Set(STATE.games.map(g => g.id));\n  const fresh = STATE.games.length ? r.games.filter(g => !before.has(g.id)) : [];\n  STATE = { ...STATE, games: r.games, me: r.me, replayApi: r.replayApi };\n  try { STATE.queue = localStorage.getItem(\"custy-review-queue\") || \"all\"; } catch (e) {}\n  $(\"who\").textContent = r.me?.gameName ? `${r.me.gameName}#${r.me.tagLine}` : \"\";\n  const note = r.note ? `<div class=\"note\">${esc(r.note)}</div>` : \"\";\n  if (!r.games.length) {\n    $(\"list\").innerHTML = note + `<div class=\"note\">No ranked or normal Summoner's Rift games found yet. Play one with the app running, then reopen this.</div>`;\n    return;\n  }\n  STATE.note = note;\n  if (fresh.length) STATE.current = null;   // a new game came in: open it\n  renderList(true);\n  if (!fresh.length && STATE.games.length && lastRefreshClicked) toast(\"No new games yet. League can take a minute or two after a game to add it to your history.\");\n  lastRefreshClicked = false;\n}\nlet lastRefreshClicked = false, lastLoad = Date.now();\n$(\"refresh\").onclick = () => { lastRefreshClicked = true; lastLoad = Date.now(); loadList().catch(e => toast(e.message)); };\n// Also look for new games when you come back to this window, and every 2 minutes while it's open.\nconst autoRefresh = () => { if (Date.now() - lastLoad > 30000) { lastLoad = Date.now(); loadList().catch(() => {}); } };\nwindow.addEventListener(\"focus\", autoRefresh);\nsetInterval(() => { if (!document.hidden) autoRefresh(); }, 120000);\n\nfunction renderList(openFirst) {\n  const shown = STATE.games.filter(g => STATE.queue === \"all\" || queueGroup(g.queue) === STATE.queue);\n  const filter = `<div class=\"filter\">${QUEUE_FILTERS.map(([k, label]) =>\n    `<button data-q=\"${k}\" class=\"${STATE.queue === k ? \"on\" : \"\"}\">${label}</button>`).join(\"\")}</div>`;\n  $(\"list\").innerHTML = filter + STATE.note + (shown.length ? shown.map(g => `\n    <div class=\"game ${g.win ? \"w\" : \"l\"}${g.id == STATE.current ? \" on\" : \"\"}\" data-id=\"${g.id}\">\n      <img src=\"${champIcon(g.champion)}\" alt=\"\">\n      <div class=\"t\">${esc(champName(g.champion))}${g.opponent ? ` <span class=\"sub\">vs ${esc(champName(g.opponent))}</span>` : \"\"}\n        <small>${esc(g.queue)} · ${esc(ROLE_NAME[g.role] || \"?\")} · ${new Date(g.created).toLocaleDateString(undefined, { month: \"short\", day: \"numeric\" })}</small></div>\n      <div class=\"kda\">${g.kills}/${g.deaths}/${g.assists}<small>${Math.round(g.duration / 60)}m</small></div>\n    </div>`).join(\"\") : `<div class=\"note\">No games in this queue yet.</div>`);\n  document.querySelectorAll(\".game\").forEach(el => el.onclick = () => openGame(el.dataset.id));\n  document.querySelectorAll(\".filter button\").forEach(b => b.onclick = () => {\n    STATE.queue = b.dataset.q;\n    try { localStorage.setItem(\"custy-review-queue\", STATE.queue); } catch (e) {}\n    renderList(true);\n  });\n  if (openFirst && shown.length && !shown.some(g => g.id == STATE.current)) openGame(shown[0].id);\n}\n\nasync function openGame(id) {\n  document.querySelectorAll(\".game\").forEach(el => el.classList.toggle(\"on\", el.dataset.id == id));\n  STATE.current = id;\n  $(\"view\").innerHTML = `<div class=\"empty\">Reading the game...</div>`;\n  const s = STATE.games.find(g => g.id == id);\n  let A;\n  try { A = analyse(await getGame(id)); } catch (e) { $(\"view\").innerHTML = `<div class=\"empty\">Couldn't read this game: ${esc(e.message)}</div>`; return; }\n  if (!A) { $(\"view\").innerHTML = `<div class=\"empty\">League didn't give a timeline for this game, so there's nothing to review.</div>`; return; }\n\n  // Your usual: other games on this champion and role; if fewer than 3, any champion in this role.\n  const others = STATE.games.filter(g => g.id != id && g.hasTimeline && g.role === s.role);\n  const sameChamp = others.filter(g => g.champion === s.champion).slice(0, 20);\n  const pool = sameChamp.length >= 3 ? sameChamp : others.slice(0, 20);\n  const label = sameChamp.length >= 3 ? `your last ${pool.length} ${champName(s.champion)} games` : `your last ${pool.length} ${ROLE_NAME[s.role] || \"\"} games (any champion)`;\n  const analysed = (await Promise.all(pool.map(g => getGame(g.id).then(analyse).catch(() => null)))).filter(Boolean);\n  const B = baseline(analysed);\n  if (STATE.current !== id) return;\n  const moments = findMoments(A, B);\n  render(A, B, moments, s, B ? label : null);\n}\n\nfunction timingCard(k, mine, usual, fmt, lowerIsBetter = true) {\n  const has = mine != null;\n  let cls = \"\", d = \"\";\n  if (has && usual != null) {\n    const delta = mine - usual;\n    cls = Math.abs(delta) < 1e-9 ? \"\" : (lowerIsBetter ? delta > 0 : delta < 0) ? \"bad\" : \"good\";\n    d = `usual ${fmt(usual)}`;\n  }\n  return `<div class=\"card\"><div class=\"k\">${k}</div><div class=\"v ${cls}\">${has ? fmt(mine) : \"—\"}</div><div class=\"d\">${d || \"&nbsp;\"}</div></div>`;\n}\n\nfunction render(A, B, moments, s, label) {\n  const opp = A.opp ? champName(A.opp.championId) : null;\n  const res = A.me.stats?.win ? `<span class=\"win\">Win</span>` : `<span class=\"loss\">Loss</span>`;\n  const banner = STATE.replayApi === false ? `<div class=\"banner\">Replay jumping is off in League's settings, so the replay will open at the start.\n      <button class=\"primary\" id=\"enableApi\">Turn on replay jumping</button></div>`\n    : STATE.replayApi == null ? `<div class=\"banner\">Couldn't find League's game.cfg, so replays may not jump to the moment. Set league_path if League is installed somewhere unusual.</div>` : \"\";\n  const cs10 = A.minutes >= 10 ? A.myCs[10] : null;\n  $(\"view\").innerHTML = `\n    <div class=\"vs\"><img src=\"${champIcon(A.me.championId)}\" alt=\"\">\n      <div><h1>${esc(champName(A.me.championId))}${opp ? ` <span class=\"sub\" style=\"font-size:18px\">vs ${esc(opp)}</span>` : \"\"}</h1>\n      <div class=\"sub\">${res} · ${esc(s.queue)} · ${esc(ROLE_NAME[A.role] || \"role unknown\")} · ${A.me.stats.kills}/${A.me.stats.deaths}/${A.me.stats.assists} · ${clock(A.g.gameDuration)} · ${new Date(A.g.gameCreation).toLocaleString()}</div></div></div>\n    <a class=\"btn yt\" target=\"_blank\" href=\"https://www.youtube.com/results?search_query=${encodeURIComponent(\"Domisumreplay \" + champName(A.me.championId) + (opp ? \" vs \" + opp : \"\"))}\">▶ High-elo ${esc(champName(A.me.championId))}${opp ? \" vs \" + esc(opp) : \"\"} games on YouTube</a>\n    ${banner}\n    <div class=\"tabs\"><button data-tab=\"moments\" class=\"on\">Moments</button><button data-tab=\"experts\">vs Experts</button></div>\n    <div id=\"v-experts\" hidden><div class=\"empty\">Loading expert data...</div></div>\n    <div id=\"v-moments\">\n    <h2>${A.diff ? \"Lane gold difference\" : \"Your gold\"} by minute</h2>\n    <div class=\"card\">${chart(A, B, moments)}\n      <div class=\"legend\"><span><i style=\"background:var(--gold)\"></i>This game</span>${B ? `<span><i style=\"background:var(--blue-wash);border:1px solid var(--blue)\"></i>Middle half of ${esc(label)}</span>` : \"\"}<span><i style=\"background:var(--red-wash)\"></i>Moments to watch</span><span style=\"color:var(--red-ink)\">✕ your deaths</span></div>\n      ${B ? \"\" : `<div class=\"sub\" style=\"margin-top:6px\">Not enough of your ${esc(ROLE_NAME[A.role] || \"\")} games saved yet to draw \"your usual\" (needs 3). It fills in as you play with the app running.</div>`}\n    </div>\n    <h2>Moments to watch, in order</h2>\n    <div class=\"card\">${moments.length ? moments.map((w, i) => `\n      <div class=\"moment\">\n        <div class=\"when\">${clock(w.start)} – ${clock(w.end)}${w.parts.some(p => p.kind === \"gold\") ? `<small>${Math.round(Math.max(...w.parts.filter(p => p.kind === \"gold\").map(p => p.cost))).toLocaleString()} gold lost</small>` : \"\"}</div>\n        <div class=\"what\">${w.parts.map(p => `<div class=\"part\"><b>${esc(p.title)}</b>${p.compare ? `<div class=\"cmp\">${p.compare}</div>` : \"\"}</div>`).join(\"\")}\n          ${w.context.length ? `<ul>${w.context.map(l => `<li>${l}</li>`).join(\"\")}</ul>` : \"\"}</div>\n        <div class=\"acts\"><button class=\"primary\" data-watch=\"${w.start}\">Watch in my replay</button></div>\n      </div>`).join(\"\") : `<div class=\"empty\" style=\"padding:10px 0\">Nothing stood out: your lane gold never slipped 400+ below ${B ? \"your usual\" : \"your opponent\"}, no early deaths, and your timings were on pace.</div>`}\n    </div>\n    <h2>All deaths (${A.deaths.length})</h2>\n    <div class=\"card\">${A.deaths.length ? A.deaths.map(d => deathRow(A, d)).join(\"\") : `<div class=\"empty\" style=\"padding:10px 0\">No deaths this game.</div>`}</div>\n    <h2>Timings</h2>\n    <div class=\"timings\">\n      ${timingCard(\"First back\", A.backs[0]?.t ?? null, B?.firstBack, clock)}\n      ${timingCard(\"First item\", A.firstItem, B?.firstItem, clock)}\n      ${timingCard(\"Level 6 vs \" + (opp || \"opponent\"), A.lvl6 != null && A.oppLvl6 != null ? A.lvl6 - A.oppLvl6 : null, B?.lvl6Gap, v => (v <= 0 ? Math.round(-v) + \"s ahead\" : Math.round(v) + \"s behind\"))}\n      ${timingCard(\"CS at 10:00\", cs10, B?.cs?.[10]?.p50, v => Math.round(v), false)}\n      ${timingCard(\"Deaths before 14:00\", A.deaths.filter(d => d.t < 840).length, B?.deaths14, v => Math.round(v))}\n    </div>\n    </div>\n    <p class=\"sub\" style=\"margin-top:22px\">Test version: Moments are compared with ${B ? esc(label) : \"nothing yet\"}, not high-elo players. It only says where to look; watching the replay is how you see why.</p>`;\n  document.querySelectorAll(\"[data-watch]\").forEach(b => b.onclick = () => watch(A.g.gameId, +b.dataset.watch, b));\n  const en = $(\"enableApi\"); if (en) en.onclick = enableApi;\n  const tabs = document.querySelectorAll(\".tabs button\");\n  const show = (t) => {\n    STATE.tab = t;\n    tabs.forEach(b => b.classList.toggle(\"on\", b.dataset.tab === t));\n    $(\"v-moments\").hidden = t !== \"moments\"; $(\"v-experts\").hidden = t !== \"experts\";\n  };\n  tabs.forEach(b => b.onclick = () => show(b.dataset.tab));\n  show(STATE.tab || \"moments\");\n  loadExperts(A);\n}\n\nfunction deathRow(A, d) {\n  const e = d.e, m = Math.min(A.minutes, Math.floor(d.t / 60));\n  const killers = [e.killerId, ...(e.assistingParticipantIds || [])].filter(p => p > 0).map(A.champOf);\n  const where = area(e.position?.x, e.position?.y);\n  const notes = [];\n  if (A.enemyJg && e.killerId !== A.enemyJg.participantId && !(e.assistingParticipantIds || []).includes(A.enemyJg.participantId)) {\n    const jp = A.pf(A.frames[m], A.enemyJg.participantId).position;\n    if (jp) notes.push(`enemy jungler was in ${area(jp.x, jp.y)} at ${m}:00`);\n  }\n  const unspent = A.pf(A.frames[m], A.me.participantId).currentGold;\n  if (unspent >= 900) notes.push(`about <b>${Math.round(unspent).toLocaleString()} gold</b> unspent at ${m}:00`);\n  if (A.diff) { const m2 = Math.min(A.minutes, m + 2); notes.push(`lane gold ${signed(A.diff[m])} → ${signed(A.diff[m2])} two minutes later`); }\n  const lead = A.deaths.filter(x => x.t < d.t).length;\n  return `<div class=\"moment\">\n    <div class=\"when\">${clock(d.t)}<small style=\"color:var(--mute)\">death ${lead + 1}</small></div>\n    <div class=\"what\"><div class=\"part\"><b>${killers.length ? esc(killers.join(\" + \")) : \"Executed\"}${where ? ` <span class=\"sub\">· ${esc(where)}</span>` : \"\"}</b>\n      ${notes.length ? `<div class=\"cmp\">${notes.join(\" · \")}</div>` : \"\"}</div></div>\n    <div class=\"acts\"><button class=\"primary\" data-watch=\"${Math.max(0, d.t - 30)}\">Watch in my replay</button></div>\n  </div>`;\n}\n\n// ---------------------------------------------------------------- vs Experts\nconst benchCache = {};\nasync function loadExperts(A) {\n  const champ = DD.champ[A.me.championId]?.id, role = A.role;\n  const el = $(\"v-experts\");\n  if (!champ || !role) { el.innerHTML = `<div class=\"empty\">Couldn't tell this game's champion or role.</div>`; return; }\n  const name = champ + \"-\" + role;\n  let B;\n  try { B = benchCache[name] ??= await api(\"/api/benchmark/\" + name); } catch (e) { B = { missing: true }; }\n  if (!document.body.contains(el)) return;\n  if (B.missing) {\n    el.innerHTML = `<div class=\"card\" style=\"margin-top:16px\">No expert data for <b>${esc(champName(A.me.championId))} ${esc(ROLE_NAME[role] || role)}</b> yet.\n      <div class=\"sub\" style=\"margin-top:4px\">${B.offline ? \"Couldn't reach custy.gg.\" : \"There aren't enough high-elo games on this champion in this role yet (needs 40).\"}</div></div>`;\n    return;\n  }\n  el.innerHTML = expertsView(A, B);\n  el.querySelectorAll(\"[data-watch]\").forEach(b => b.onclick = () => watch(A.g.gameId, +b.dataset.watch, b));\n  el.querySelectorAll(\".seg button\").forEach(b => b.onclick = () => {\n    el.querySelectorAll(\".seg button\").forEach(x => x.classList.toggle(\"on\", x === b));\n    el.querySelector(\"#xchart\").innerHTML = benchChart(A, B, b.dataset.k);\n  });\n}\n\nconst BP = [5, 10, 15, 20];\nconst METRICS = [\n  [\"gold\", \"Gold\", v => Math.round(v).toLocaleString()],\n  [\"cs\", \"CS\", v => Math.round(v)],\n  [\"level\", \"Level\", v => (Math.round(v * 10) / 10)],\n  [\"xpdiff\", \"XP vs lane opponent\", v => signed(v)],\n  [\"gdiff\", \"Gold vs lane opponent\", v => signed(v), \"diff\"],\n  [\"csdiff\", \"CS vs lane opponent\", v => signed(v)],\n];\nconst mine = (A, k) => ({ gdiff: A.diff, gold: A.myGold, cs: A.myCs })[k] ?? A[k];\n\nfunction findings(A, B) {\n  const out = [];\n  // Break points that fall below the experts' middle half\n  for (const [k, label, fmt] of METRICS) {\n    const s = mine(A, k); if (!s) continue;\n    for (const m of [10, 15, 20]) {\n      const b = B.minutes[k]?.[m]; if (!b || s.length <= m) continue;\n      const [p25, p50, p75] = b, spread = Math.max(1, p75 - p25);\n      if (s[m] < p25) out.push({ sev: (p25 - s[m]) / spread, t: m * 60,\n        title: `${label} at ${m}:00: ${fmt(s[m])}`, text: `Experts: ${fmt(p50)} (middle half ${fmt(p25)} to ${fmt(p75)}).` });\n    }\n  }\n  // Keep the worst minute per metric\n  const seen = new Set(); const dedup = out.sort((a, b) => b.sev - a.sev).filter(f => { const k = f.title.split(\" at \")[0]; if (seen.has(k)) return false; seen.add(k); return true; });\n  // Items\n  const items = B.items, byId = Object.fromEntries(items.map(i => [i.id, i]));\n  A.items.slice(0, 5).forEach((b, n) => {\n    const e = byId[b.id], slot = n + 1;\n    if (!e) { dedup.push({ sev: 0.8, t: b.t, title: `${itemName(b.id)} (item ${slot})`, text: `Experts on ${champName(A.me.championId)} almost never build it.` }); return; }\n    const key = isArmorPen(b.id) ? \"armor\" + Math.min(A.armorN, 2) : isMagicPen(b.id) ? \"mr\" + Math.min(A.mrN, 2) : null;\n    const r = key && e.by[key] ? e.by[key][0] / Math.max(1, e.by[key][1]) : e.rate;\n    if (e.rate < 0.2) dedup.push({ sev: 0.7, t: b.t, title: `${itemName(b.id)} as item ${slot}`, text: `Only ${Math.round(e.rate * 100)}% of expert games build it at all.` });\n    else if (slot >= e.slot + 2 && key && r < 0.4) dedup.push({ sev: 0.5, t: b.t, title: `${itemName(b.id)} came ${ord(slot)}, at ${clock(b.t)}`,\n      text: `Experts who build it usually get it ${ord(Math.round(e.slot))} (~${clock(e.time)}), but only ${Math.round(r * 100)}% of their games ${defenseText(key)} include it. Against this team it wasn't urgent.` });\n    else if (slot >= e.slot + 2) dedup.push({ sev: 1 + (slot - e.slot) * 0.3, t: b.t, title: `${itemName(b.id)} came ${ord(slot)}, at ${clock(b.t)}`,\n      text: `Experts buy it ${ord(Math.round(e.slot))}, around ${clock(e.time)}${key ? `, and ${Math.round(r * 100)}% of their games ${defenseText(key)} include it` : \"\"}.` });\n  });\n  // Items experts usually get in games like this that you didn't\n  const mineIds = new Set(A.items.slice(0, 4).map(b => b.id));\n  for (const e of items) {\n    if (mineIds.has(e.id)) continue;\n    const key = isArmorPen(e.id) ? \"armor\" + Math.min(A.armorN, 2) : isMagicPen(e.id) ? \"mr\" + Math.min(A.mrN, 2) : null;\n    if (!key || !e.by[key] || e.by[key][1] < 8) continue;\n    const r = e.by[key][0] / e.by[key][1];\n    if (r >= 0.6 && A.minutes >= 22) dedup.push({ sev: 1.2, t: e.time, title: `No ${e.name} in your first 4 items`, text: `Experts build it in ${Math.round(r * 100)}% of games ${defenseText(key)}, usually ${ord(Math.round(e.slot))}.` });\n  }\n  // Timings\n  const T = B.timings, cmp = (mineV, b, title, fmt, worse) => {\n    if (mineV == null || !b) return; const [p25, p50, p75] = b;\n    if (worse(mineV, p25, p75)) dedup.push({ sev: 0.9, t: null, title: `${title}: ${fmt(mineV)}`, text: `Experts: ${fmt(p50)} (middle half ${fmt(p25)} to ${fmt(p75)}).` });\n  };\n  cmp(A.backs[0]?.t, T.first_back, \"First back\", clock, (v, lo, hi) => v > hi + 30);\n  cmp(A.firstItem, T.legendary1, \"First item\", clock, (v, lo, hi) => v > hi);\n  cmp(A.deaths.filter(d => d.t < 840).length, T.deaths_14, \"Deaths before 14:00\", v => Math.round(v), (v, lo, hi) => v > hi);\n  cmp(A.deaths.length, T.deaths, \"Deaths\", v => Math.round(v), (v, lo, hi) => v > hi);\n  if (A.lvl6 != null && A.oppLvl6 != null) cmp(A.lvl6 - A.oppLvl6, T.lvl6_gap, \"Level 6 vs your opponent\", v => (v <= 0 ? Math.round(-v) + \"s ahead\" : Math.round(v) + \"s behind\"), (v, lo, hi) => v > hi + 15);\n  return dedup.sort((a, b) => b.sev - a.sev).slice(0, 6);\n}\nconst ord = (n) => n + ([\"th\", \"st\", \"nd\", \"rd\"][n % 100 > 10 && n % 100 < 14 ? 0 : n % 10] || \"th\");\nconst isArmorPen = (id) => /armor penetration|lethality/i.test(DD.items[id]?.description || \"\") || (DD.items[id]?.stats?.FlatArmorPenetrationMod || 0) > 0 || /Dominik|Mortal Reminder|Serylda|Black Cleaver/i.test(itemName(id));\nconst isMagicPen = (id) => /magic penetration/i.test(DD.items[id]?.description || \"\") || /Void Staff|Cryptbloom|Shadowflame/i.test(itemName(id));\nconst defenseText = (key) => ({ armor0: \"where no enemy built armor\", armor1: \"where one enemy built armor\", armor2: \"where two or more enemies built armor\",\n  mr0: \"where no enemy built magic resist\", mr1: \"where one enemy built magic resist\", mr2: \"where two or more enemies built magic resist\" })[key];\n\nfunction expertsView(A, B) {\n  const champ = champName(A.me.championId), F = findings(A, B);\n  const cell = (k, m, fmt) => {\n    const s = mine(A, k), b = B.minutes[k]?.[m];\n    if (!s || s.length <= m) return `<td class=\"sub\">—</td>`;\n    const cls = b ? (s[m] < b[0] ? \"bad\" : s[m] > b[2] ? \"good\" : \"\") : \"\";\n    return `<td><span class=\"y ${cls}\">${fmt(s[m])}</span>${b ? `<span class=\"e\">experts ${fmt(b[1])} (${fmt(b[0])} to ${fmt(b[2])})</span>` : \"\"}</td>`;\n  };\n  const byId = Object.fromEntries(B.items.map(i => [i.id, i]));\n  const tRow = (label, mineV, b, fmt, lowerBetter = true) => {\n    const cls = mineV == null || !b ? \"\" : lowerBetter ? (mineV > b[2] ? \"bad\" : mineV < b[0] ? \"good\" : \"\") : (mineV < b[0] ? \"bad\" : mineV > b[2] ? \"good\" : \"\");\n    return `<tr><td>${label}</td><td><span class=\"y ${cls}\">${mineV == null ? \"—\" : fmt(mineV)}</span></td><td>${b ? fmt(b[1]) : \"—\"}</td><td class=\"sub\">${b ? fmt(b[0]) + \" to \" + fmt(b[2]) : \"\"}</td></tr>`;\n  };\n  const T = B.timings;\n  return `\n  <p class=\"sub\" style=\"margin:14px 0 0\">Compared with <b>${B.games}</b> ranked games from <b>${B.players}</b> ${/onetricks/.test(B.source || \"\") ? `top ${esc(champ)} one-tricks on onetricks.gg` : `Master+ players on ${esc(champ)}`} (${esc(B.regions.join(\", \"))}), built ${esc(B.built)}. Expert numbers are the middle game (median) and the middle half of their games.</p>\n\n  <h2>What stands out</h2>\n  <div class=\"card\">${F.length ? F.map(f => `<div class=\"finding\"><b>${esc(f.title)}</b><span>${f.text}</span>\n      ${f.t != null ? ` <button style=\"margin-left:8px;padding:2px 8px\" data-watch=\"${Math.max(0, f.t - 30)}\">Watch ${clock(Math.max(0, f.t - 30))}</button>` : \"\"}</div>`).join(\"\")\n    : `<div class=\"empty\" style=\"padding:10px 0\">You were within the experts' usual range on everything checked.</div>`}</div>\n\n  <h2>Break points</h2>\n  <div class=\"card\"><table class=\"grid\"><tr><th></th>${BP.map(m => `<th>${m}:00</th>`).join(\"\")}</tr>\n    ${METRICS.map(([k, label, fmt]) => `<tr><td>${label}</td>${BP.map(m => cell(k, m, fmt)).join(\"\")}</tr>`).join(\"\")}</table></div>\n\n  <h2>Over the game</h2>\n  <div class=\"card\"><div class=\"seg\">${METRICS.filter(([k]) => mine(A, k)).map(([k, label], i) => `<button data-k=\"${k}\" class=\"${i ? \"\" : \"on\"}\">${label}</button>`).join(\"\")}</div>\n    <div id=\"xchart\">${benchChart(A, B, \"gold\")}</div>\n    <div class=\"legend\"><span><i style=\"background:var(--gold)\"></i>You</span><span><i style=\"background:var(--blue-wash);border:1px solid var(--blue)\"></i>Middle half of expert games</span><span style=\"color:var(--red-ink)\">✕ your deaths</span></div></div>\n\n  <h2>Build</h2>\n  <div class=\"card\"><table class=\"grid\"><tr><th>Your items</th><th>Bought</th><th>Experts</th><th>How often experts build it</th></tr>\n    ${A.items.slice(0, 6).map((b, n) => { const e = byId[b.id]; return `<tr><td>${n + 1}. ${esc(itemName(b.id))}</td><td>${clock(b.t)}</td>\n      <td>${e ? `usually ${ord(Math.round(e.slot))}, ~${clock(e.time)}` : \"—\"}</td><td>${e ? Math.round(e.rate * 100) + \"%\" : \"rarely\"}</td></tr>`; }).join(\"\") || `<tr><td colspan=\"4\" class=\"sub\">No completed items.</td></tr>`}\n  </table>\n  <div class=\"sub\" style=\"margin-top:10px\">Enemies who built armor: <b>${A.armorN}</b> · magic resist: <b>${A.mrN}</b>. Most common expert starts:\n    ${B.orders.slice(0, 3).map(([ids, c]) => `<div>${ids.map(itemName).map(esc).join(\" › \")} <span style=\"color:var(--faint)\">(${c} games)</span></div>`).join(\"\")}</div></div>\n\n  <h2>Timings</h2>\n  <div class=\"card\"><table class=\"grid\"><tr><th></th><th>You</th><th>Experts</th><th>Middle half</th></tr>\n    ${tRow(\"First back\", A.backs[0]?.t ?? null, T.first_back, clock)}\n    ${tRow(\"Gold spent on first back\", A.backs[0]?.spent ?? null, T.first_back_gold, v => Math.round(v).toLocaleString(), false)}\n    ${tRow(\"Backs before 14:00\", A.backs.filter(b => b.t < 840).length, T.backs_before_14, v => Math.round(v), false)}\n    ${tRow(\"First item\", A.firstItem, T.legendary1, clock)}\n    ${tRow(\"Second item\", A.items[1]?.t ?? null, T.legendary2, clock)}\n    ${tRow(\"Level 6 vs opponent (s)\", A.lvl6 != null && A.oppLvl6 != null ? A.lvl6 - A.oppLvl6 : null, T.lvl6_gap, v => (v <= 0 ? Math.round(-v) + \"s ahead\" : Math.round(v) + \"s behind\"))}\n    ${tRow(\"Deaths before 14:00\", A.deaths.filter(d => d.t < 840).length, T.deaths_14, v => Math.round(v))}\n    ${tRow(\"Deaths\", A.deaths.length, T.deaths, v => Math.round(v))}\n  </table></div>`;\n}\n\nfunction benchChart(A, B, k) {\n  const curve = mine(A, k), band = B.minutes[k] || [];\n  if (!curve) return `<div class=\"sub\">Not available for this game.</div>`;\n  const W = 1000, H = 240, L = 56, R = 12, T = 12, Bm = 26, n = A.minutes;\n  let lo = Math.min(...curve), hi = Math.max(...curve);\n  band.slice(0, n + 1).forEach(b => { if (b) { lo = Math.min(lo, b[0]); hi = Math.max(hi, b[2]); } });\n  if (k.endsWith(\"diff\")) { lo = Math.min(lo, 0); hi = Math.max(hi, 0); }\n  const pad = (hi - lo) * .08 || 1; lo -= pad; hi += pad;\n  const x = m => L + (m / n) * (W - L - R), y = v => T + (hi - v) / (hi - lo) * (H - T - Bm);\n  const fmt = METRICS.find(mm => mm[0] === k)[2];\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" width=\"100%\">`;\n  for (let i = 0; i <= 4; i++) { const v = lo + (hi - lo) * i / 4; s += `<line x1=\"${L}\" x2=\"${W - R}\" y1=\"${y(v)}\" y2=\"${y(v)}\" stroke=\"var(--line-soft)\"/><text x=\"${L - 6}\" y=\"${y(v) + 4}\" text-anchor=\"end\">${fmt(v)}</text>`; }\n  if (k.endsWith(\"diff\")) s += `<line x1=\"${L}\" x2=\"${W - R}\" y1=\"${y(0)}\" y2=\"${y(0)}\" stroke=\"var(--line)\"/>`;\n  for (let m = 0; m <= n; m += 5) s += `<text x=\"${x(m)}\" y=\"${H - 8}\" text-anchor=\"middle\">${m}:00</text>`;\n  const pts = band.slice(0, n + 1).map((b, m) => b && [m, b]).filter(Boolean);\n  if (pts.length > 1) {\n    s += `<path d=\"M${pts.map(([m, b]) => x(m) + \",\" + y(b[2])).join(\"L\")}L${pts.slice().reverse().map(([m, b]) => x(m) + \",\" + y(b[0])).join(\"L\")}Z\" fill=\"var(--blue-wash)\"/>`;\n    s += `<path d=\"M${pts.map(([m, b]) => x(m) + \",\" + y(b[1])).join(\"L\")}\" fill=\"none\" stroke=\"var(--blue)\" stroke-opacity=\".5\" stroke-dasharray=\"4 4\"/>`;\n  }\n  s += `<path d=\"M${curve.map((v, m) => x(m) + \",\" + y(v)).join(\"L\")}\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"2.5\"/>`;\n  curve.forEach((v, m) => { const b = band[m]; s += `<circle cx=\"${x(m)}\" cy=\"${y(v)}\" r=\"6\" fill=\"transparent\"><title>${m}:00  you ${fmt(v)}${b ? \"  ·  experts \" + fmt(b[1]) : \"\"}</title></circle>`; });\n  for (const d of A.deaths) { const m = Math.min(n, Math.round(d.t / 60)); s += `<text x=\"${x(d.t / 60)}\" y=\"${y(curve[m]) - 8}\" text-anchor=\"middle\" style=\"fill:var(--red-ink);font-size:13px\">✕</text>`; }\n  return s + \"</svg>\";\n}\n\nlet toastTimer;\nfunction toast(msg, sticky) {\n  const t = $(\"toast\"); t.textContent = msg; t.style.display = \"block\";\n  clearTimeout(toastTimer); if (!sticky) toastTimer = setTimeout(() => t.style.display = \"none\", 7000);\n}\nasync function watch(gameId, t, btn) {\n  document.querySelectorAll(\"[data-watch]\").forEach(b => b.disabled = true);\n  try { await api(`/api/replay/${gameId}?t=${t}`, { method: \"POST\" }); }\n  catch (e) { toast(e.message); document.querySelectorAll(\"[data-watch]\").forEach(b => b.disabled = false); return; }\n  toast(\"Opening the replay...\", true);\n  const poll = async () => {\n    const r = await api(\"/api/replay\").catch(() => ({ state: \"error\", message: \"Lost touch with the app.\" }));\n    toast(r.message, r.state === \"working\");\n    if (r.state === \"working\") setTimeout(poll, 1200);\n    else document.querySelectorAll(\"[data-watch]\").forEach(b => b.disabled = false);\n  };\n  poll();\n}\nasync function enableApi() {\n  try {\n    const r = await api(\"/api/replay-setup\", { method: \"POST\" });\n    STATE.replayApi = r.replayApi;\n    toast(\"Replay jumping is on. It applies to the next replay you open.\");\n    if (STATE.current) openGame(STATE.current);\n  } catch (e) { toast(\"Couldn't change League's settings: \" + e.message); }\n}\n\nloadDD().then(loadList).catch(e => { $(\"list\").innerHTML = `<div class=\"note\">Couldn't load: ${esc(e.message)}</div>`; });\n</script>\n</body>\n</html>\n",
  "review.py": "\"\"\"\nGame review (test version).\n\nA small page, served only to this computer, that reviews your recent\nSummoner's Rift games (ranked, normals, quickplay; not customs): your lane gold\ndifference by minute, the moments it slipped, your back, item and level 6\ntimings, and a button that opens your replay at that moment.\n\nGames and timelines read from the League client stay on this computer, in\nreview-cache/ next to the app's log, so the comparison with \"your usual\" grows\nas you play with the app running. Two things come from the site: the item\npurchases and skill-ups the client leaves out of ranked games (the app sends\nthe game's id; the site looks them up with its Riot key), and the expert\nnumbers for the \"vs Experts\" tab.\n\n    python custy_collector.py --review     open it without the Windows app\n\"\"\"\n\nimport json\nimport os\nimport re\nimport secrets\nimport ssl\nimport sys\nimport threading\nimport time\nimport urllib.error\nimport urllib.request\nfrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\nfrom urllib.parse import parse_qs, urlparse\n\ncore = sys.modules.get(\"custy_collector\") or sys.modules[\"__main__\"]\n\nCACHE_DIR = os.path.join(core.HERE, \"review-cache\")\nINFO_PATH = os.path.join(core.HERE, \"review.json\")   # where the running app's page is\nCACHE_LIMIT = 400          # games kept on disk (oldest dropped first)\nHISTORY_DEPTH = 100        # how far back to look in the client's match history\nREPLAY_API = \"https://127.0.0.1:2999\"\nSR_MAP = 11\n\nQUEUES = {420: \"Ranked Solo/Duo\", 440: \"Ranked Flex\", 400: \"Normal Draft\", 430: \"Normal Blind\",\n          490: \"Quickplay\", 480: \"Swiftplay\", 700: \"Clash\"}\n\n# The role quest slot (stats.roleBoundItem) names each player's role. Same table as lib/normalize.ts.\nQUEST_ROLE = {\n    1090: \"TOP\", 1200: \"TOP\", 1220: \"TOP\", 1221: \"TOP\", 1222: \"TOP\",\n    1094: \"JUNGLE\", 1204: \"JUNGLE\", 1205: \"JUNGLE\", 1209: \"JUNGLE\", 1210: \"JUNGLE\", 1211: \"JUNGLE\",\n    1091: \"MID\", 1201: \"MID\", 1206: \"MID\",\n    1092: \"BOT\", 1202: \"BOT\", 1207: \"BOT\",\n    1093: \"SUPPORT\", 1203: \"SUPPORT\", 1208: \"SUPPORT\", 2055: \"SUPPORT\", 2056: \"SUPPORT\",\n}\nBOOTS = {1001, 2422, 3005, 3006, 3008, 3009, 3010, 3013, 3020, 3047, 3111, 3117, 3158, 3168, 3170,\n         3171, 3172, 3173, 3174, 3175, 3176}\nKEEP_EVENTS = {\"CHAMPION_KILL\", \"ELITE_MONSTER_KILL\", \"BUILDING_KILL\", \"ITEM_PURCHASED\", \"ITEM_UNDO\",\n               \"ITEM_SOLD\", \"SKILL_LEVEL_UP\", \"TURRET_PLATE_DESTROYED\"}\nFRAME_FIELDS = (\"totalGold\", \"currentGold\", \"minionsKilled\", \"jungleMinionsKilled\", \"level\", \"xp\", \"position\")\n\n_lock = threading.Lock()\n_bench = {}   # name -> (fetched_at, data or None)\n_replay = {\"state\": \"idle\", \"message\": \"\", \"game\": None, \"at\": 0}\n\n\n# --------------------------------------------------------------------------\n# Reading games from the client, with a local cache\n# --------------------------------------------------------------------------\n\ndef _num(v):\n    try:\n        return int(v)\n    except (TypeError, ValueError):\n        return 0\n\n\ndef roles(game):\n    \"\"\"participantId -> TOP/JUNGLE/MID/BOT/SUPPORT, from the role quest slot, else a guess.\"\"\"\n    out = {}\n    for team in (100, 200):\n        players = [p for p in game.get(\"participants\") or [] if _num(p.get(\"teamId\")) == team]\n        taken = set()\n        for p in players:\n            st = p.get(\"stats\") or {}\n            r = QUEST_ROLE.get(_num(st.get(\"roleBoundItem\"))) or (\"BOT\" if _num(st.get(\"roleBoundItem\")) in BOOTS else \"\")\n            if r and r not in taken:\n                out[p[\"participantId\"]] = r\n                taken.add(r)\n        rest = [p for p in players if p[\"participantId\"] not in out]\n        for p in rest:  # fall back to Smite, then the lane the game saw\n            tl = p.get(\"timeline\") or {}\n            lane, sub = str(tl.get(\"lane\") or \"\").upper(), str(tl.get(\"role\") or \"\").upper()\n            guess = (\"JUNGLE\" if 11 in (_num(p.get(\"spell1Id\")), _num(p.get(\"spell2Id\"))) else\n                     \"TOP\" if lane == \"TOP\" else \"MID\" if lane in (\"MIDDLE\", \"MID\") else\n                     \"SUPPORT\" if sub == \"DUO_SUPPORT\" else \"BOT\" if sub == \"DUO_CARRY\" else \"\")\n            if guess and guess not in taken:\n                out[p[\"participantId\"]] = guess\n                taken.add(guess)\n        rest = sorted([p for p in players if p[\"participantId\"] not in out],\n                      key=lambda p: -_num((p.get(\"stats\") or {}).get(\"totalMinionsKilled\")))\n        left = [r for r in (\"TOP\", \"MID\", \"BOT\", \"JUNGLE\", \"SUPPORT\") if r not in taken]\n        for p, r in zip(rest, left):\n            out[p[\"participantId\"]] = r\n    return out\n\n\ndef _is_reviewable(summary):\n    if summary.get(\"gameType\") == \"CUSTOM_GAME\":\n        return False\n    m = summary.get(\"mapId\")\n    return m in (None, SR_MAP) and str(summary.get(\"gameMode\") or \"CLASSIC\") == \"CLASSIC\"\n\n\ndef _slim_timeline(tl):\n    frames = []\n    for f in tl.get(\"frames\") or []:\n        pfs = f.get(\"participantFrames\") or {}\n        items = pfs.values() if isinstance(pfs, dict) else pfs\n        slim = {}\n        for pf in items:\n            pid = str(pf.get(\"participantId\"))\n            slim[pid] = {k: pf.get(k) for k in FRAME_FIELDS if k in pf}\n        frames.append({\"timestamp\": f.get(\"timestamp\"), \"participantFrames\": slim,\n                       \"events\": [e for e in f.get(\"events\") or [] if e.get(\"type\") in KEEP_EVENTS]})\n    return {\"frames\": frames}\n\n\ndef _cache_path(game_id):\n    return os.path.join(CACHE_DIR, \"%s.json\" % int(game_id))\n\n\ndef _read_cache(game_id):\n    try:\n        with open(_cache_path(game_id), \"r\", encoding=\"utf-8\") as f:\n            return json.load(f)\n    except (OSError, ValueError):\n        return None\n\n\ndef _write_cache(game_id, data):\n    os.makedirs(CACHE_DIR, exist_ok=True)\n    tmp = _cache_path(game_id) + \".tmp\"\n    with open(tmp, \"w\", encoding=\"utf-8\") as f:\n        json.dump(data, f)\n    os.replace(tmp, _cache_path(game_id))\n\n\n_index = {}   # file name -> (mtime, the small facts list_games and refresh need)\n\n\ndef _info(name):\n    \"\"\"Summary facts about one cached game, without re-reading its (large) file unless it changed.\"\"\"\n    path = os.path.join(CACHE_DIR, name)\n    try:\n        mtime = os.path.getmtime(path)\n    except OSError:\n        _index.pop(name, None)\n        return None\n    hit = _index.get(name)\n    if hit and hit[0] == mtime:\n        return hit[1]\n    data = _read_cache(name[:-5])\n    info = None\n    if data:\n        info = {\"summary\": data.get(\"summary\"), \"me\": data.get(\"me\"), \"hasTimeline\": data.get(\"timeline\") is not None,\n                \"reviewable\": _is_reviewable(data.get(\"game\") or {}), \"tlTried\": float(data.get(\"tlTried\") or 0),\n                \"created\": (data.get(\"game\") or {}).get(\"gameCreation\") or 0}\n    _index[name] = (mtime, info)\n    return info\n\n\ndef _prune_cache():\n    \"\"\"Keeps the newest CACHE_LIMIT games (by when they were played).\"\"\"\n    try:\n        names = [n for n in os.listdir(CACHE_DIR) if n.endswith(\".json\")]\n    except OSError:\n        return\n    if len(names) <= CACHE_LIMIT:\n        return\n    names.sort(key=lambda n: (_info(n) or {}).get(\"created\") or 0)\n    for name in names[:-CACHE_LIMIT]:\n        try:\n            os.remove(os.path.join(CACHE_DIR, name))\n        except OSError:\n            pass\n        _index.pop(name, None)\n\n\ndef _summarize(game, me_puuid):\n    \"\"\"The few fields the game list needs.\"\"\"\n    idents = {i.get(\"participantId\"): (i.get(\"player\") or {}) for i in game.get(\"participantIdentities\") or []}\n    rl = roles(game)\n    me = None\n    for p in game.get(\"participants\") or []:\n        if idents.get(p[\"participantId\"], {}).get(\"puuid\") == me_puuid:\n            me = p\n    if me is None:\n        return None\n    opp = next((p for p in game[\"participants\"] if _num(p.get(\"teamId\")) != _num(me.get(\"teamId\"))\n                and rl.get(p[\"participantId\"]) == rl.get(me[\"participantId\"])), None)\n    st = me.get(\"stats\") or {}\n    return {\n        \"id\": game.get(\"gameId\"), \"created\": game.get(\"gameCreation\"), \"duration\": game.get(\"gameDuration\"),\n        \"queue\": QUEUES.get(_num(game.get(\"queueId\")), \"Queue %s\" % game.get(\"queueId\")),\n        \"version\": game.get(\"gameVersion\"),\n        \"champion\": me.get(\"championId\"), \"role\": rl.get(me[\"participantId\"], \"\"),\n        \"opponent\": opp.get(\"championId\") if opp else None,\n        \"win\": bool(st.get(\"win\")), \"kills\": st.get(\"kills\"), \"deaths\": st.get(\"deaths\"), \"assists\": st.get(\"assists\"),\n        \"cs\": _num(st.get(\"totalMinionsKilled\")) + _num(st.get(\"neutralMinionsKilled\")),\n    }\n\n\n_cfg = {}\n\n\ndef _has_purchases(tl):\n    return any(e.get(\"type\") == \"ITEM_PURCHASED\" for f in (tl or {}).get(\"frames\") or [] for e in f.get(\"events\") or [])\n\n\ndef fill_from_riot(data):\n    \"\"\"The client's timeline for ranked/normal games has no item purchases or skill-ups.\n    Asks the site, which gets them from Riot's match API, and merges them in. Returns True if it changed anything.\"\"\"\n    tl, game = data.get(\"timeline\"), data.get(\"game\") or {}\n    if not tl or _has_purchases(tl) or not _cfg.get(\"site_url\"):\n        return False\n    # \"fillTried2\": attempts made before the site had its Riot key don't count.\n    if time.time() - float(data.get(\"fillTried2\") or 0) < 600:\n        return False\n    data[\"fillTried2\"] = time.time()\n    url = \"%s/api/review/timeline?platform=%s&gameId=%s\" % (_cfg[\"site_url\"].rstrip(\"/\"), game.get(\"platformId\") or \"NA1\", game.get(\"gameId\"))\n    req = urllib.request.Request(url, headers={\"Authorization\": \"Bearer \" + _cfg.get(\"ingest_key\", \"\"),\n                                               \"User-Agent\": \"custy-collector/\" + core.VERSION})\n    try:\n        with urllib.request.urlopen(req, timeout=30) as r:\n            extra = json.loads(r.read())\n    except Exception as e:\n        core.log.info(\"Review: couldn't get item data for %s from the site: %s\", game.get(\"gameId\"), e)\n        return True   # remember when we tried\n    # Riot's participant numbers -> the client's, matched by player\n    by_puuid = {(i.get(\"player\") or {}).get(\"puuid\"): i.get(\"participantId\") for i in game.get(\"participantIdentities\") or []}\n    pid_map = {p[\"participantId\"]: by_puuid.get(p[\"puuid\"], p[\"participantId\"]) for p in extra.get(\"participants\") or []}\n    frames = tl.get(\"frames\") or []\n    added = 0\n    for f in extra.get(\"frames\") or []:\n        for e in f.get(\"events\") or []:\n            e = dict(e)\n            if \"participantId\" in e:\n                e[\"participantId\"] = pid_map.get(e[\"participantId\"], e[\"participantId\"])\n            if not frames:\n                break\n            idx = min(len(frames) - 1, int((e.get(\"timestamp\") or 0) // 60000) + 1)\n            frames[idx].setdefault(\"events\", []).append(e)\n            added += 1\n    for f in frames:\n        f[\"events\"] = sorted(f.get(\"events\") or [], key=lambda e: e.get(\"timestamp\") or 0)\n    data[\"filled\"] = added\n    core.log.info(\"Review: added %d item and skill events to game %s from Riot\", added, game.get(\"gameId\"))\n    return True\n\n\ndef _lcu(cfg):\n    creds = core.find_client(cfg)\n    return core.LeagueClient(*creds) if creds else None\n\n\ndef fetch_game(lcu, game_id, me_puuid):\n    \"\"\"Game + timeline from the cache, or from the client (then cached).\"\"\"\n    data = _read_cache(game_id)\n    if data and data.get(\"timeline\") is not None:\n        return data\n    if lcu is None:\n        return data\n    game = lcu.get(\"/lol-match-history/v1/games/%s\" % game_id)\n    if not game or not game.get(\"participants\"):\n        return None\n    try:\n        tl = _slim_timeline(lcu.get(\"/lol-match-history/v1/game-timelines/%s\" % game_id) or {})\n    except (urllib.error.URLError, OSError, ValueError):\n        tl = None\n    data = {\"game\": game, \"timeline\": tl if tl and tl[\"frames\"] else None,\n            \"summary\": _summarize(game, me_puuid), \"me\": me_puuid, \"tlTried\": time.time()}\n    fill_from_riot(data)\n    _write_cache(game_id, data)\n    return data\n\n\ndef refresh(cfg):\n    \"\"\"Reads any reviewable games in the client's history that aren't cached yet. Returns (me, error).\"\"\"\n    lcu = _lcu(cfg)\n    if lcu is None:\n        return None, \"League isn't open. Showing games saved earlier.\"\n    me = core.current_player(lcu)\n    if not me.get(\"puuid\"):\n        return None, \"League is open but not logged in yet.\"\n    try:\n        data = lcu.get(\"/lol-match-history/v1/products/lol/current-summoner/matches?begIndex=0&endIndex=%d\" % HISTORY_DEPTH)\n    except (urllib.error.URLError, OSError, ValueError) as e:\n        return me, \"Couldn't read match history: %s\" % e\n    games = (data or {}).get(\"games\") or {}\n    if isinstance(games, dict):\n        games = games.get(\"games\") or []\n    for s in games:\n        if not _is_reviewable(s) or not s.get(\"gameId\"):\n            continue\n        cached = _info(\"%s.json\" % int(s[\"gameId\"]))\n        # Already saved; a game the client had no timeline for is retried at most every 10 minutes.\n        if cached and (cached[\"hasTimeline\"] or time.time() - cached[\"tlTried\"] < 600):\n            continue\n        try:\n            fetch_game(lcu, s[\"gameId\"], me[\"puuid\"])\n        except (urllib.error.URLError, OSError, ValueError) as e:\n            core.log.info(\"Review: couldn't read game %s: %s\", s.get(\"gameId\"), e)\n    _prune_cache()\n    return me, None\n\n\ndef list_games(me_puuid=None):\n    out = []\n    try:\n        names = os.listdir(CACHE_DIR)\n    except OSError:\n        return out\n    for n in names:\n        if not n.endswith(\".json\"):\n            continue\n        info = _info(n)\n        if not info or not info[\"summary\"] or not info[\"reviewable\"]:\n            continue\n        if me_puuid and info[\"me\"] != me_puuid:\n            continue\n        out.append(dict(info[\"summary\"], hasTimeline=info[\"hasTimeline\"]))\n    out.sort(key=lambda s: s.get(\"created\") or 0, reverse=True)\n    return out\n\n\n# --------------------------------------------------------------------------\n# Replays: download, start, and jump to a time\n# --------------------------------------------------------------------------\n\ndef league_dir(cfg):\n    dirs = ([cfg[\"league_path\"]] if cfg.get(\"league_path\") else []) + list(core.DEFAULT_LEAGUE_DIRS)\n    for d in dirs:\n        if os.path.exists(os.path.join(d, \"lockfile\")) or os.path.isdir(os.path.join(d, \"Config\")):\n            return d\n    m = re.search(r'--install-directory=([^\"]+?)(?:\"|\\s--|$)', core._client_command_line())\n    return m.group(1).strip() if m else None\n\n\ndef _game_cfg(cfg):\n    d = league_dir(cfg)\n    return os.path.join(d, \"Config\", \"game.cfg\") if d else None\n\n\ndef replay_api_enabled(cfg):\n    path = _game_cfg(cfg)\n    if not path or not os.path.exists(path):\n        return None\n    try:\n        with open(path, \"r\", encoding=\"utf-8\", errors=\"replace\") as f:\n            text = f.read()\n    except OSError:\n        return None\n    return bool(re.search(r\"(?im)^\\s*EnableReplayApi\\s*=\\s*1\\s*$\", text))\n\n\ndef enable_replay_api(cfg):\n    \"\"\"Adds EnableReplayApi=1 under [General] in League's game.cfg (keeps a backup of the original).\"\"\"\n    path = _game_cfg(cfg)\n    if not path or not os.path.exists(path):\n        raise ValueError(\"Couldn't find League's Config/game.cfg\")\n    with open(path, \"r\", encoding=\"utf-8\", errors=\"replace\") as f:\n        text = f.read()\n    backup = path + \".custy-backup\"\n    if not os.path.exists(backup):\n        with open(backup, \"w\", encoding=\"utf-8\") as f:\n            f.write(text)\n    nl = \"\\r\\n\" if \"\\r\\n\" in text else \"\\n\"\n    if re.search(r\"(?im)^\\s*EnableReplayApi\\s*=\", text):\n        text = re.sub(r\"(?im)^(\\s*EnableReplayApi\\s*=).*$\", r\"\\g<1>1\", text)\n    elif re.search(r\"(?im)^\\[General\\]\\s*$\", text):\n        text = re.sub(r\"(?im)^(\\[General\\]\\s*?)$\", lambda m: m.group(1) + nl + \"EnableReplayApi=1\", text, count=1)\n    else:\n        text = text.rstrip() + nl + nl + \"[General]\" + nl + \"EnableReplayApi=1\" + nl\n    with open(path, \"w\", encoding=\"utf-8\", newline=\"\") as f:\n        f.write(text)\n\n\ndef _local_ctx():\n    # League's local servers use self-signed certificates; only ever used for 127.0.0.1.\n    ctx = ssl.create_default_context()\n    ctx.check_hostname = False\n    ctx.verify_mode = ssl.CERT_NONE\n    return ctx\n\n\ndef _lcu_post(lcu, path, body):\n    req = urllib.request.Request(lcu.base + path, data=json.dumps(body).encode(), method=\"POST\",\n                                 headers=dict(lcu.headers, **{\"Content-Type\": \"application/json\"}))\n    with urllib.request.urlopen(req, context=lcu.ctx, timeout=20) as r:\n        raw = r.read()\n    return json.loads(raw) if raw else None\n\n\ndef _playback(body=None):\n    data = json.dumps(body).encode() if body is not None else None\n    req = urllib.request.Request(REPLAY_API + \"/replay/playback\", data=data, method=\"POST\" if body is not None else \"GET\",\n                                 headers={\"Content-Type\": \"application/json\"})\n    with urllib.request.urlopen(req, context=_local_ctx(), timeout=5) as r:\n        return json.loads(r.read() or b\"{}\")\n\n\ndef _status(state, message, **extra):\n    with _lock:\n        _replay.update(state=state, message=message, at=time.time(), **extra)\n    core.log.info(\"Replay: %s\", message)\n\n\ndef _clock(t):\n    t = max(0, int(t))\n    return \"%d:%02d\" % (t // 60, t % 60)\n\n\ndef _live(path):\n    req = urllib.request.Request(REPLAY_API + path)\n    with urllib.request.urlopen(req, context=_local_ctx(), timeout=5) as r:\n        return json.loads(r.read() or b\"null\")\n\n\ndef _replay_is_game(game_id):\n    \"\"\"True/False if the open replay is (not) this game, None if we can't tell.\"\"\"\n    data = _read_cache(game_id)\n    if not data:\n        return None\n    try:   # the replay's length is the game's length\n        length, dur = float(_playback().get(\"length\") or 0), float((data.get(\"game\") or {}).get(\"gameDuration\") or 0)\n        if length and dur and abs(length - dur) > 20:\n            return False\n    except Exception:\n        pass\n    want = set()\n    for i in (data.get(\"game\") or {}).get(\"participantIdentities\") or []:\n        pl = i.get(\"player\") or {}\n        if pl.get(\"gameName\"):\n            want.add((\"%s#%s\" % (pl.get(\"gameName\"), pl.get(\"tagLine\") or \"\")).lower())\n    try:\n        players = _live(\"/liveclientdata/playerlist\") or []\n    except Exception:\n        return None\n    seen = {str(p.get(\"riotId\") or \"\").lower() for p in players if p.get(\"riotId\")}\n    if not want or not seen:\n        return None\n    return len(want & seen) >= len(want) - 1   # same ten players (allowing one renamed)\n\n\ndef _replay_playing():\n    \"\"\"The replay has finished loading and its clock is running (seeking any earlier gets ignored).\"\"\"\n    try:\n        if not _playback().get(\"length\"):\n            return False\n        if (_live(\"/liveclientdata/gamestats\") or {}).get(\"gameTime\") is None:\n            return False\n        a = float(_playback().get(\"time\") or 0)\n        time.sleep(1.5)\n        pb = _playback()\n        return float(pb.get(\"time\") or 0) > a or bool(pb.get(\"paused\"))\n    except Exception:\n        return False\n\n\ndef _seek(seconds):\n    \"\"\"Jumps and waits for the jump to finish before checking it (re-sending mid-seek restarts it).\"\"\"\n    target = float(seconds)\n    for attempt in range(4):\n        _status(\"working\", \"Jumping to %s...\" % _clock(target))\n        try:\n            _playback({\"time\": target, \"paused\": False})\n        except Exception as e:\n            core.log.info(\"Replay seek %d failed: %s\", attempt + 1, e)\n        # Long jumps take a few seconds while the replay catches up; wait until it's done.\n        settled_at = time.time() + 20\n        now = None\n        while time.time() < settled_at:\n            time.sleep(1)\n            try:\n                pb = _playback()\n            except Exception:\n                continue\n            if pb.get(\"seeking\"):\n                continue\n            now = float(pb.get(\"time\") or 0)\n            if target - 3 <= now <= target + 20:\n                return _status(\"done\", \"Jumped to %s.\" % _clock(target))\n            if time.time() > settled_at - 14:   # gave it 6s without seeking: it didn't take\n                break\n        core.log.info(\"Replay seek %d landed at %s, wanted %s\", attempt + 1, now, target)\n        time.sleep(1.5)\n    return _status(\"done\", \"Replay is open, but the jump didn't stick. Drag the timeline to %s.\" % _clock(target))\n\n\ndef _open_replay(cfg, game_id, seconds):\n    try:\n        lcu = _lcu(cfg)\n        if lcu is None:\n            return _status(\"error\", \"Open League first: replays are played through the client.\")\n        # A replay already open? Jump in it if it's this game; otherwise it has to be closed first.\n        try:\n            open_now = bool(_playback().get(\"length\"))\n        except Exception:\n            open_now = False\n        if open_now:\n            if _replay_is_game(game_id) is False:\n                return _status(\"error\", \"A different replay is open. Close it, then click Watch again.\")\n            return _seek(seconds)\n\n        meta = lcu.get(\"/lol-replays/v1/metadata/%s\" % game_id) or {}\n        state = meta.get(\"state\")\n        if state in (\"incompatible\", \"unsupported\"):\n            return _status(\"error\", \"This replay is from an older patch, so League can't play it. \"\n                                    \"Moments still show their times.\")\n        if state in (\"lost\", \"missingOrExpired\", \"error\"):\n            return _status(\"error\", \"League no longer has this replay (state: %s).\" % state)\n        if state != \"watch\":\n            _status(\"working\", \"Downloading the replay...\")\n            try:\n                _lcu_post(lcu, \"/lol-replays/v1/rofls/%s/download\" % game_id, {\"componentType\": \"replay-button_match-history\"})\n            except urllib.error.HTTPError as e:\n                core.log.info(\"Replay download request: HTTP %s\", e.code)\n            for _ in range(120):\n                time.sleep(1)\n                meta = lcu.get(\"/lol-replays/v1/metadata/%s\" % game_id) or {}\n                if meta.get(\"state\") == \"watch\":\n                    break\n                if meta.get(\"state\") in (\"incompatible\", \"unsupported\", \"lost\", \"missingOrExpired\", \"error\"):\n                    return _status(\"error\", \"League couldn't get this replay (state: %s).\" % meta.get(\"state\"))\n                pct = meta.get(\"downloadProgress\")\n                if pct:\n                    _status(\"working\", \"Downloading the replay... %s%%\" % pct)\n            else:\n                return _status(\"error\", \"The replay didn't finish downloading. Try again in a minute.\")\n\n        _status(\"working\", \"Starting the replay...\")\n        _lcu_post(lcu, \"/lol-replays/v1/rofls/%s/watch\" % game_id, {\"componentType\": \"replay-button_match-history\"})\n\n        if replay_api_enabled(cfg) is False:\n            return _status(\"done\", \"Replay is starting. Jumping isn't turned on, so drag the timeline to %s.\" % _clock(seconds))\n\n        _status(\"working\", \"Waiting for the replay to load...\")\n        deadline = time.time() + 240\n        while time.time() < deadline:\n            time.sleep(2)\n            if _replay_playing():\n                return _seek(seconds)\n        return _status(\"error\", \"The replay didn't open within 4 minutes. If it opened, drag the timeline to %s.\" % _clock(seconds))\n    except Exception as e:\n        _status(\"error\", \"Couldn't open the replay: %s\" % e)\n\n\n# --------------------------------------------------------------------------\n# The local web server\n# --------------------------------------------------------------------------\n\ndef _page():\n    base = getattr(sys, \"_MEIPASS\", os.path.dirname(os.path.abspath(__file__)))\n    with open(os.path.join(base, \"review.html\"), \"rb\") as f:\n        return f.read()\n\n\ndef benchmark(cfg, name):\n    \"\"\"High-elo numbers for one champion and role, from the site (refreshed every few hours).\"\"\"\n    hit = _bench.get(name)\n    if hit and time.time() - hit[0] < (600 if hit[1].get(\"missing\") else 6 * 3600):\n        return hit[1]\n    data = {\"missing\": True}\n    try:\n        url = cfg[\"site_url\"].rstrip(\"/\") + \"/benchmarks/%s.json\" % name\n        req = urllib.request.Request(url, headers={\"User-Agent\": \"custy-collector/\" + core.VERSION})\n        with urllib.request.urlopen(req, timeout=15) as r:\n            data = json.loads(r.read())\n    except urllib.error.HTTPError as e:\n        if e.code != 404 and hit:\n            return hit[1]\n    except Exception:\n        if hit:\n            return hit[1]\n        return {\"missing\": True, \"offline\": True}\n    _bench[name] = (time.time(), data)\n    return data\n\n\ndef make_handler(cfg, token):\n    me_cache = {\"me\": None}\n\n    class Handler(BaseHTTPRequestHandler):\n        def log_message(self, *a):\n            pass\n\n        def _send(self, code, body, ctype=\"application/json\"):\n            data = body if isinstance(body, bytes) else json.dumps(body).encode()\n            self.send_response(code)\n            self.send_header(\"Content-Type\", ctype)\n            self.send_header(\"Content-Length\", str(len(data)))\n            self.send_header(\"Cache-Control\", \"no-store\")\n            self.end_headers()\n            self.wfile.write(data)\n\n        def _allowed(self):\n            # Only this computer, only our own page (stops other sites from poking it).\n            host = (self.headers.get(\"Host\") or \"\").split(\":\")[0]\n            if host not in (\"127.0.0.1\", \"localhost\"):\n                return False\n            return secrets.compare_digest(self.headers.get(\"X-Custy-Key\") or \"\", token)\n\n        def do_GET(self):\n            url = urlparse(self.path)\n            if url.path == \"/\":\n                host = (self.headers.get(\"Host\") or \"\").split(\":\")[0]\n                if host not in (\"127.0.0.1\", \"localhost\") or parse_qs(url.query).get(\"k\", [\"\"])[0] != token:\n                    return self._send(403, b\"Open this from the custy.gg app.\", \"text/plain\")\n                return self._send(200, _page(), \"text/html; charset=utf-8\")\n            if url.path == \"/api/ping\":\n                return self._send(200, {\"ok\": True})\n            if not self._allowed():\n                return self._send(403, {\"error\": \"forbidden\"})\n            if url.path == \"/api/games\":\n                me, err = refresh(cfg)\n                if me:\n                    me_cache[\"me\"] = me\n                me = me_cache[\"me\"]\n                games = list_games(me.get(\"puuid\") if me else None)\n                return self._send(200, {\"me\": me, \"note\": err, \"games\": games,\n                                        \"replayApi\": replay_api_enabled(cfg)})\n            m = re.match(r\"^/api/game/(\\d+)$\", url.path)\n            if m:\n                me = me_cache[\"me\"] or {}\n                data = _read_cache(m.group(1)) or fetch_game(_lcu(cfg), m.group(1), me.get(\"puuid\"))\n                if not data:\n                    return self._send(404, {\"error\": \"game not found\"})\n                if fill_from_riot(data):\n                    _write_cache(m.group(1), data)\n                return self._send(200, dict(data, roles=roles(data[\"game\"])))\n            m = re.match(r\"^/api/benchmark/([A-Za-z]+-(?:TOP|JUNGLE|MID|BOT|SUPPORT))$\", url.path)\n            if m:\n                return self._send(200, benchmark(cfg, m.group(1)))\n            if url.path == \"/api/replay\":\n                with _lock:\n                    return self._send(200, dict(_replay))\n            return self._send(404, {\"error\": \"not found\"})\n\n        def do_POST(self):\n            url = urlparse(self.path)\n            if not self._allowed():\n                return self._send(403, {\"error\": \"forbidden\"})\n            m = re.match(r\"^/api/replay/(\\d+)$\", url.path)\n            if m:\n                try:\n                    t = max(0.0, float(parse_qs(url.query).get(\"t\", [\"0\"])[0]))\n                except ValueError:\n                    return self._send(400, {\"error\": \"bad time\"})\n                with _lock:\n                    busy = _replay[\"state\"] == \"working\" and time.time() - _replay[\"at\"] < 200\n                if busy:\n                    return self._send(409, {\"error\": \"A replay is already being opened.\"})\n                _status(\"working\", \"Opening the replay...\", game=m.group(1))\n                threading.Thread(target=_open_replay, args=(cfg, m.group(1), t), daemon=True).start()\n                return self._send(202, {\"ok\": True})\n            if url.path == \"/api/replay-setup\":\n                try:\n                    enable_replay_api(cfg)\n                    return self._send(200, {\"ok\": True, \"replayApi\": replay_api_enabled(cfg)})\n                except Exception as e:\n                    return self._send(500, {\"error\": str(e)})\n            return self._send(404, {\"error\": \"not found\"})\n\n    return Handler\n\n\ndef start(cfg, port=0):\n    \"\"\"Starts the page in a background thread. Returns its address (with the access key).\"\"\"\n    _cfg.update(cfg)\n    token = secrets.token_urlsafe(18)\n    # A fixed port when it's free, so the page keeps its saved choices (like the queue filter) between restarts.\n    server = None\n    for p in ([port] if port else [47821, 0]):\n        try:\n            server = ThreadingHTTPServer((\"127.0.0.1\", p), make_handler(cfg, token))\n            break\n        except OSError:\n            continue\n    url = \"http://127.0.0.1:%d/?k=%s\" % (server.server_address[1], token)\n    threading.Thread(target=server.serve_forever, name=\"review\", daemon=True).start()\n    try:\n        with open(INFO_PATH, \"w\", encoding=\"utf-8\") as f:\n            json.dump({\"url\": url, \"pid\": os.getpid()}, f)\n    except OSError:\n        pass\n    core.log.info(\"Game review page ready\")\n    return url\n\n\ndef running_url():\n    \"\"\"The page address of an app that's already running, or None.\"\"\"\n    try:\n        with open(INFO_PATH, \"r\", encoding=\"utf-8\") as f:\n            url = json.load(f).get(\"url\")\n        base = url.split(\"/?\")[0]\n        with urllib.request.urlopen(base + \"/api/ping\", timeout=2) as r:\n            if r.status == 200:\n                return url\n    except Exception:\n        pass\n    return None\n\n\ndef open_window(url):\n    \"\"\"Opens the page in its own app-style window (Edge or Chrome), else the normal browser.\"\"\"\n    import subprocess\n    import webbrowser\n    if sys.platform == \"win32\":\n        candidates = []\n        for env in (\"PROGRAMFILES(X86)\", \"PROGRAMFILES\", \"LOCALAPPDATA\"):\n            root = os.environ.get(env)\n            if root:\n                candidates += [os.path.join(root, r\"Microsoft\\Edge\\Application\\msedge.exe\"),\n                               os.path.join(root, r\"Google\\Chrome\\Application\\chrome.exe\")]\n        for exe in candidates:\n            if os.path.exists(exe):\n                try:\n                    subprocess.Popen([exe, \"--app=\" + url, \"--window-size=1280,900\"], close_fds=True)\n                    return\n                except OSError:\n                    pass\n    webbrowser.open(url)\n\n\ndef keep_cache_fresh(cfg, stop):\n    \"\"\"Saves new games to the review cache after each game, so 'your usual' keeps growing.\"\"\"\n    stop.wait(90)\n    last = None\n    while not stop.is_set():\n        try:\n            lcu = _lcu(cfg)\n            phase = lcu.get(\"/lol-gameflow/v1/gameflow-phase\") if lcu else None\n            if lcu and phase not in (\"InProgress\", \"Reconnect\", \"GameStart\") and phase != last:\n                refresh(cfg)\n            last = phase\n        except Exception as e:\n            core.log.info(\"Review cache: %s\", e)\n        stop.wait(120)\n\n\ndef serve_forever(cfg):\n    \"\"\"For --review outside the Windows app: serve the page until Ctrl+C.\"\"\"\n    url = start(cfg)\n    print(\"Game review: \" + url)\n    open_window(url)\n    try:\n        while True:\n            time.sleep(3600)\n    except KeyboardInterrupt:\n        pass\n",
  "windows-autostart-off.bat": "@echo off\nrem Stops the collector from starting with Windows and stops the running copy.\nset \"VBS=%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\custy-collector.vbs\"\nif exist \"%VBS%\" del \"%VBS%\"\npowershell -NoProfile -Command \"Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -like '*custy_collector.py*' } | ForEach-Object { Stop-Process -Id $_.ProcessId -Force }\"\necho Autostart removed and collector stopped.\npause\n",
  "windows-autostart-on.bat": "@echo off\nrem Starts the collector hidden every time you log in to Windows, and starts it now.\nsetlocal\ncd /d \"%~dp0\"\nset \"SCRIPT=%~dp0custy_collector.py\"\n\nrem Find the windowless Python (pythonw), so no console window stays open.\nset \"PYW=\"\nfor /f \"delims=\" %%i in ('where pythonw 2^>nul') do if not defined PYW set \"PYW=%%i\"\nif not defined PYW for /f \"delims=\" %%i in ('where pyw 2^>nul') do if not defined PYW set \"PYW=%%i\"\nif not defined PYW (\n  echo Python was not found. Install it from https://www.python.org/downloads/ and tick \"Add python.exe to PATH\".\n  pause\n  exit /b 1\n)\nif not exist \"%~dp0config.json\" (\n  echo config.json is missing. Copy config.example.json to config.json and fill it in first.\n  pause\n  exit /b 1\n)\n\nrem Ask Windows where this user's Startup folder is (it can be moved, e.g. by OneDrive), and create it if needed.\nset \"STARTUP=\"\nfor /f \"usebackq delims=\" %%i in (`powershell -NoProfile -Command \"[Environment]::GetFolderPath('Startup')\"`) do set \"STARTUP=%%i\"\nif not defined STARTUP set \"STARTUP=%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\"\nif not exist \"%STARTUP%\" mkdir \"%STARTUP%\"\n\nset \"VBS=%STARTUP%\\custy-collector.vbs\"\n> \"%VBS%\" echo CreateObject(\"WScript.Shell\").Run \"\"\"%PYW%\"\" \"\"%SCRIPT%\"\"\", 0, False\nif not exist \"%VBS%\" (\n  echo Could not create the startup file in:\n  echo   %STARTUP%\n  echo Run windows-start.bat instead to keep the collector running in a window.\n  pause\n  exit /b 1\n)\n\nrem Stop any copy that's already running, then start one hidden.\npowershell -NoProfile -Command \"Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -like '*custy_collector.py*' } | ForEach-Object { Stop-Process -Id $_.ProcessId -Force }\" >nul 2>nul\nstart \"\" wscript \"%VBS%\"\n\necho Done. The collector is running in the background and will start again whenever you log in to Windows.\necho You can close this window. Activity is written to collector.log in this folder.\npause\n",
  "windows-start.bat": "@echo off\nrem Runs the collector in this window. Close the window to stop it.\ncd /d \"%~dp0\"\nwhere py >nul 2>nul && (py -3 custy_collector.py %* & goto :end)\nwhere python >nul 2>nul && (python custy_collector.py %* & goto :end)\necho Python was not found. Install it from https://www.python.org/downloads/ and tick \"Add python.exe to PATH\".\n:end\npause\n",
  "windows-test.bat": "@echo off\nrem Checks that config.json is right, the site is reachable and League is found.\ncd /d \"%~dp0\"\nwhere py >nul 2>nul && (py -3 custy_collector.py --test & goto :end)\nwhere python >nul 2>nul && (python custy_collector.py --test & goto :end)\necho Python was not found. Install it from https://www.python.org/downloads/ and tick \"Add python.exe to PATH\".\n:end\npause\n"
};
